// ===================== mvvm/ObservableArray.h =====================
// SPDX-License-Identifier: Apache-2.0
// TObservableArray<T> — 要素の追加・削除・変更を通知する配列
//
// 使い方:
//   TObservableArray<int> inv;
//
//   inv.Subscribe([](EArrayChange kind, usize idx, const int* v, void*){
//       switch (kind) {
//           case EArrayChange::Inserted: ACS_LOG_INFO("Add[%zu] = %d", idx, *v); break;
//           case EArrayChange::Removed:  ACS_LOG_INFO("Remove[%zu]", idx);       break;
//           case EArrayChange::Changed:  ACS_LOG_INFO("Set[%zu] = %d", idx, *v); break;
//           case EArrayChange::Cleared:  ACS_LOG_INFO("Cleared all");            break;
//       }
//   }, nullptr);
//
//   inv.PushBack(7);     // → Inserted, idx=0, v=7
//   inv.SetAt(0, 99);    // → Changed,  idx=0, v=99
//   inv.RemoveAt(0);     // → Removed,  idx=0
//   inv.Clear();         // → Cleared
//
// 設計:
//   ・通知は 1 種類の callback で kind を分岐 (UE5 の per-event fan-out より易い)
//   ・listener 中は PushBack/PopBack/RemoveAt/SetAt/Clear による全変更を禁止する
//     (Debug は assert 検出。assert 無効の Release では検出されず処理が実行されるため、
//      呼び出した時点で caller の契約違反)
//     → どうしても要るなら listener が処理キューに積んで後で実行
//   ・要素の T は同値判定 (operator==) を持つこと推奨 (Set で同値スキップ)


namespace acs {

namespace mvvm_test {
struct FObservableArrayLifetimeTestAccess;
} // namespace mvvm_test

/** 配列の変更内容を表す通知種別。 */
enum class EArrayChange : u8 {
    /** index に value を挿入した。 */
    Inserted,

    /** index にあった要素を削除した (削除済みのため通知時の value は nullptr)。 */
    Removed,

    /** index の要素を別の値に書き換えた (value = 新値)。 */
    Changed,

    /** 全要素を削除した (index=0, value=nullptr)。 */
    Cleared,
};

/**
 * TObservableArray の購読を識別するハンドル (TObservable<T> と同仕様)。
 *
 * @details id と generation の組でスロット再利用後の古いハンドルを無効化する。
 */
struct FArrayObserverHandle {
    /** スロットの 1-based インデックス (0 は無効)。 */
    u32 id         = 0;

    /** スロット世代 (再利用のたびに増加)。 */
    u32 generation = 0;

    /**
     * ハンドルが有効かを返す。
     *
     * @return id が 0 でなければ true。
     */
    bool IsValid() const noexcept { return id != 0; }

    /**
     * 2 つのハンドルが同一購読を指すかを比較する。
     *
     * @param o 比較相手のハンドル。
     * @return id と generation が一致すれば true。
     */
    bool operator==(const FArrayObserverHandle& o) const noexcept {
        return id == o.id && generation == o.generation;
    }
};

/** 無効を表す既定構築の配列購読ハンドル。 */
inline constexpr FArrayObserverHandle kInvalidArrayObserver{};

/**
 * 要素の挿入・削除・変更・全消去を通知する観測可能配列。
 *
 * @details
 * 各変更操作は単一のリスナを EArrayChange の種別付きで呼ぶ (per-event の fan-out はしない)。
 * 通知中 (Notify 内) は PushBack/PopBack/RemoveAt/SetAt/Clear による全変更を禁止する。
 * Debug ビルドでは assert で検出する。assert を無効化した Release ビルドでは検出されず
 * 変更処理が実行されるため、呼び出した時点で caller の契約違反となる。
 * SetAt は通知外でも operator== で同値ならスキップする。
 * リスナが配列自身または配列を所有する object を破棄した場合、実行中の通知を直ちに打ち切り、
 * 解放済みの購読スロットへ戻らない。破棄を行ったリスナ自身も、value / user / owner が
 * 以後無効になり得るため、破棄操作を最後の処理として直ちに return しなければならない。
 *
 * @tparam T 要素型 (operator== を持つこと推奨)。
 */
template<typename T>
class TObservableArray {
public:
    /** 変更通知リスナ型 (種別・index・該当値ポインタ・user を受け取る)。 */
    using Listener = void (*)(EArrayChange kind, usize index, const T* value, void* user);

    /** 空配列を構築する。 */
    TObservableArray() noexcept = default;

    /**
     * 配列を破棄する。
     *
     * @details 通知 callback から自身が破棄された場合は、stack 上の全 Notify frame を
     * dead にして、callback 復帰後の通知処理が this を再参照しないようにする。
     */
    ~TObservableArray() noexcept {
        InvalidateNotifyFrames();
    }

    /** コピー禁止 (購読スロットを単独所有するため)。 */
    TObservableArray(const TObservableArray&)            = delete;

    /** コピー代入も禁止。 */
    TObservableArray& operator=(const TObservableArray&) = delete;

    /**
     * 末尾に要素を追加し Inserted を通知する。
     *
     * @param v 追加する要素 (ムーブで取り込む)。
     */
    void PushBack(T v) noexcept {
        AssertMutationOK();
        const usize idx = m_Items.Size();
        m_Items.PushBack(Move(v));
        Notify(EArrayChange::Inserted, idx, &m_Items[idx]);
    }

    /**
     * 末尾要素を削除し Removed を通知する (空なら何もしない)。
     */
    void PopBack() noexcept {
        if (m_Items.Size() == 0) return;
        AssertMutationOK();
        const usize idx = m_Items.Size() - 1;
        // PopBack 後は要素アクセスできないので value=nullptr で通知
        m_Items.PopBack();
        Notify(EArrayChange::Removed, idx, nullptr);
    }

    /**
     * 指定 index の要素を削除し Removed を通知する。
     *
     * @details 末尾入れ替えではなく後続要素を前詰めして順序を保持する。範囲外なら何もしない。
     * @param index 削除する要素の位置。
     */
    void RemoveAt(usize index) noexcept {
        if (index >= m_Items.Size()) return;
        AssertMutationOK();
        for (usize i = index + 1; i < m_Items.Size(); ++i) {
            m_Items[i - 1] = Move(m_Items[i]);
        }
        m_Items.PopBack();
        Notify(EArrayChange::Removed, index, nullptr);
    }

    /**
     * 指定 index の要素を書き換え Changed を通知する。
     *
     * @details 範囲外なら何もしない。既存値と operator== で同値なら通知せずスキップする。
     * @param index 書き換える要素の位置。
     * @param v 設定する新しい値 (ムーブで取り込む)。
     */
    void SetAt(usize index, T v) noexcept {
        if (index >= m_Items.Size()) return;
        if (m_Items[index] == v) return;
        AssertMutationOK();
        m_Items[index] = Move(v);
        Notify(EArrayChange::Changed, index, &m_Items[index]);
    }

    /**
     * 全要素を削除し Cleared を通知する (空なら何もしない)。
     */
    void Clear() noexcept {
        if (m_Items.Size() == 0) return;
        AssertMutationOK();
        m_Items.Clear();
        Notify(EArrayChange::Cleared, 0, nullptr);
    }

    /**
     * 要素数を返す。
     *
     * @return 現在の要素数。
     */
    usize Size() const noexcept { return m_Items.Size(); }

    /**
     * 空かどうかを返す。
     *
     * @return 要素が無ければ true。
     */
    bool  Empty() const noexcept { return m_Items.Size() == 0; }

    /**
     * 指定 index の要素への const 参照を返す。
     *
     * @param index 取得する要素の位置 (範囲チェックなし)。
     * @return 要素への const 参照。
     */
    const T& At(usize index) const noexcept { return m_Items[index]; }

    /**
     * 指定 index の要素への可変参照を返す。
     *
     * @details 直接書き換えても通知は走らないので、変更通知が要るなら SetAt を使う。
     * @param index 取得する要素の位置 (範囲チェックなし)。
     * @return 要素への可変参照。
     */
    T&       At(usize index)       noexcept { return m_Items[index]; }

    /**
     * 内部配列先頭への const ポインタを返す。
     *
     * @return 要素配列の先頭 (空なら実装依存)。
     */
    const T* Data() const noexcept { return m_Items.Data(); }

    /**
     * 内部配列先頭への可変ポインタを返す。
     *
     * @return 要素配列の先頭 (空なら実装依存)。
     */
    T*       Data()       noexcept { return m_Items.Data(); }

    /**
     * 変更通知リスナを登録する。
     *
     * @details 空きスロットを再利用し、無ければ追加する。cb が null なら無効ハンドルを返す。
     * @param cb 変更時に呼ぶリスナ (null なら登録しない)。
     * @param user リスナへそのまま渡される任意ポインタ。
     * @return 登録した購読を指すハンドル (cb が null なら kInvalidArrayObserver)。
     */
    FArrayObserverHandle Subscribe(Listener cb, void* user) noexcept {
        if (!cb) return kInvalidArrayObserver;
        u32 idx;
        if (m_FreeIndices.Size() > 0) {
            idx = m_FreeIndices[m_FreeIndices.Size() - 1];
            m_FreeIndices.PopBack();
        } else {
            idx = static_cast<u32>(m_Slots.Size());
            m_Slots.PushBack(FSlot{});
        }
        FSlot& s = m_Slots[idx];
        if (s.id == 0) s.id = m_NextId++;
        s.generation++;
        s.active = true;
        s.cb     = cb;
        s.user   = user;
        return FArrayObserverHandle{ s.id, s.generation };
    }

    /**
     * 変更通知リスナを解除する。
     *
     * @details
     * 通知中 (m_NotifyDepth>0) ならスロットを inactive にして遅延回収へ積み、
     * 通知外なら即座に空きにして再利用へ回す。
     * @param h Subscribe が返したハンドル。
     * @return 該当購読を解除できたら true、無効・未登録なら false。
     */
    bool Unsubscribe(FArrayObserverHandle h) noexcept {
        if (!h.IsValid()) return false;
        for (usize i = 0; i < m_Slots.Size(); ++i) {
            FSlot& s = m_Slots[i];
            if (s.id == h.id && s.generation == h.generation && s.active) {
                if (m_NotifyDepth > 0) {
                    s.active = false;
                    m_PendingCancel.PushBack(static_cast<u32>(i));
                } else {
                    s.active = false;
                    s.cb     = nullptr;
                    s.user   = nullptr;
                    m_FreeIndices.PushBack(static_cast<u32>(i));
                }
                return true;
            }
        }
        return false;
    }

    /**
     * 現在アクティブなリスナ数を返す。
     *
     * @return active なスロット数。
     */
    u32 SubscriberCount() const noexcept {
        u32 n = 0;
        for (usize i = 0; i < m_Slots.Size(); ++i) if (m_Slots[i].active) ++n;
        return n;
    }

private:
    /** 寿命安全テストから private Notify frame chain だけを検証するための内部 seam。 */
    friend struct mvvm_test::FObservableArrayLifetimeTestAccess;

    /**
     * 実行中 Notify の stack frame。
     *
     * @details
     * frame 自身は呼び出し側 stack に置き、確保を行わない。配列のデストラクタは
     * m_Owner を nullptr にするだけで、破棄後に frame が解放済み this を触らない。
     * 同一配列の nested Notify は変更禁止契約に反するが、assert 無効ビルドでは caller の
     * 契約違反を検出できない。その経路で self 破棄されても外側 frame を残さないよう、
     * m_Previous で実行中 chain 全体を保持する。
     */
    struct FNotifyFrame {
        explicit FNotifyFrame(TObservableArray& owner) noexcept
            : m_Owner(&owner),
              m_Previous(owner.m_ActiveNotifyFrame) {
            owner.m_ActiveNotifyFrame = this;
        }

        ~FNotifyFrame() noexcept {
            if (!m_Owner) return;
            ACS_ASSERT(m_Owner->m_ActiveNotifyFrame == this);
            m_Owner->m_ActiveNotifyFrame = m_Previous;
        }

        FNotifyFrame(const FNotifyFrame&) = delete;
        FNotifyFrame& operator=(const FNotifyFrame&) = delete;

        /** owner が callback 中に破棄されていなければ true。 */
        bool IsOwnerAlive() const noexcept { return m_Owner != nullptr; }

        TObservableArray* m_Owner = nullptr;
        FNotifyFrame* m_Previous = nullptr;
    };

    /**
     * 破棄中の配列を待っている全 Notify frame を dead にする。
     *
     * @details frame はすべて現在 thread の生存 stack 上にある。各 frame の owner だけを
     * 無効化し、配列の member storage を解放した後に this へ戻らないようにする。
     */
    void InvalidateNotifyFrames() noexcept {
        FNotifyFrame* frame = m_ActiveNotifyFrame;
        while (frame) {
            FNotifyFrame* const previous = frame->m_Previous;
            frame->m_Owner = nullptr;
            frame = previous;
        }
        m_ActiveNotifyFrame = nullptr;
    }

    /**
     * 通知中の変更操作が行われていないかを検証する。
     *
     * @details
     * リスナ (Notify) 実行中の PushBack/PopBack/RemoveAt/SetAt/Clear は、
     * 要素配列の再配置、通知の再入、通知対象の途中変更を招くためすべて禁止する。
     * Debug ビルドでは m_NotifyDepth==0 を assert する。assert を無効化した Release
     * ビルドでは検出されず変更処理が続くため、caller が契約を守らなければならない。
     */
    void AssertMutationOK() const noexcept {
        // listener 中の全変更を Debug で検出する。assert 無効構成では処理を止めないため、
        // callback 側が必ず通知後の処理キューへ遅延する。
        ACS_ASSERTF(m_NotifyDepth == 0,
                    "ObservableArray: mutation during Notify is not allowed (depth=%d)",
                    m_NotifyDepth);
    }

    /**
     * 全アクティブリスナへ 1 件の変更を通知する。
     *
     * @details
     * m_NotifyDepth で再入を数え、通知中に積まれた遅延解除を最外ループ終了時に回収する。
     * リスナ呼び出し前に関数と user をローカルへ退避し、復帰直後は stack 上の
     * FNotifyFrame だけを確認する。owner が破棄済みなら this を参照せず return する。
     * @param kind 通知する変更種別。
     * @param index 変更が起きた要素の位置。
     * @param value 該当値へのポインタ (削除/全消去では nullptr)。
     */
    void Notify(EArrayChange kind, usize index, const T* value) noexcept {
        FNotifyFrame notify_frame(*this);
        ++m_NotifyDepth;
        const usize n = m_Slots.Size();
        for (usize i = 0; i < n; ++i) {
            FSlot& s = m_Slots[i];
            if (!s.active || !s.cb) continue;
            const Listener callback = s.cb;
            void* const user = s.user;
            callback(kind, index, value, user);
            if (!notify_frame.IsOwnerAlive()) return;
        }
        --m_NotifyDepth;
        if (m_NotifyDepth == 0 && m_PendingCancel.Size() > 0) {
            for (usize i = 0; i < m_PendingCancel.Size(); ++i) {
                const u32 idx = m_PendingCancel[i];
                if (idx < m_Slots.Size()) {
                    FSlot& s = m_Slots[idx];
                    s.cb   = nullptr;
                    s.user = nullptr;
                    m_FreeIndices.PushBack(idx);
                }
            }
            m_PendingCancel.Clear();
        }
    }

    /** 1 リスナ分の購読スロット。 */
    struct FSlot {
        /** スロット ID (ハンドル照合に使う)。 */
        u32      id          = 0;

        /** 世代カウンタ (再利用のたびに増やしハンドルを陳腐化させる)。 */
        u32      generation  = 0;

        /** このスロットが現在有効かを示す。 */
        bool     active      = false;

        /** 通知時に呼ぶリスナ関数。 */
        Listener cb          = nullptr;

        /** リスナへ渡す user ポインタ。 */
        void*    user        = nullptr;
    };

    /** 保持している要素列。 */
    TArray<T>     m_Items;

    /** 購読スロット配列 (空き分は再利用される)。 */
    TArray<FSlot>  m_Slots;

    /** 空きスロットのインデックス (再利用候補)。 */
    TArray<u32>   m_FreeIndices;

    /** 通知中に解除されたスロットの遅延回収待ちインデックス。 */
    TArray<u32>   m_PendingCancel;

    /** 次に割り当てるスロット ID (1 から増加)。 */
    u32          m_NextId      = 1;

    /** 通知の再入深度 (>0 の間は解除を遅延し変更を禁止する)。 */
    i32          m_NotifyDepth = 0;

    /** 現在実行中の最内 Notify frame (未通知時は nullptr、非所有)。 */
    FNotifyFrame* m_ActiveNotifyFrame = nullptr;
};

} // namespace acs

// ===================== mvvm/ViewModel.h =====================
// SPDX-License-Identifier: Apache-2.0
// FViewModel — MVVM の M-V-VM のうち中央の VM 基底クラス
//
// MVVM は **一般的な UI architecture pattern** (WPF / Xamarin / Vue / React 等で
// 共通) であり、UE5 の UMG FViewModel 専用の概念ではない。
// ACS の MVVM は次の 3 層で構成される:
//   Model     = ゲームロジック / アセット / ECS 内のデータ
//   View      = src/ui/ の FWidget tree (FLabel / FButton / FSlider 等)、または
//               src/imgui/ の ImGui (ad-hoc デバッグ用、本番 UI は src/ui/ 推奨)
//   FViewModel = この基底を継承して TObservable<T> プロパティを公開するクラス
//
// 使い方:
//   class FPlayerViewModel : public FViewModel {
//   public:
//       TObservable<f32>     hp     { 100.0f };
//       TObservable<f32>     mana   { 50.0f };
//       TObservable<i32>     level  { 1 };
//       TObservable<bool>    invincible { false };
//   };
//
//   // モデル (実データ) からの反映:
//   void OnDamage(FPlayerViewModel& vm, f32 dmg) {
//       vm.hp.Set(vm.hp.Get() - dmg);    // 自動的に View 側へ propagate
//   }
//
// 設計:
//   ・基底はあえて空 (RTTI なしでも識別不要)。命名と意図のみ提供。
//   ・派生クラスが TObservable<T> をメンバに持って公開する
//   ・View 側は Subscribe / Bind で監視する


namespace acs {

/**
 * MVVM の FViewModel 基底クラス。
 *
 * @details
 * 本体はあえて空で (RTTI 不要・識別子なし)、命名と意図のみを提供する。派生クラスが
 * TObservable<T> をメンバとして公開し、View 側は Subscribe / Bind でそれを監視する。
 * Model のデータ更新を TObservable.Set で反映すると View へ自動伝播する。
 */
class FViewModel {
public:
    /** 空の FViewModel を構築する。 */
    FViewModel() noexcept = default;

    /** 派生クラスを正しく破棄するための仮想デストラクタ。 */
    virtual ~FViewModel() noexcept = default;

    /** コピー禁止 (TObservable メンバの購読を単独所有するため)。 */
    FViewModel(const FViewModel&) = delete;

    /** コピー代入も禁止。 */
    FViewModel& operator=(const FViewModel&) = delete;
};

} // namespace acs

// ===================== network/IpAddress.h =====================
// SPDX-License-Identifier: Apache-2.0
// IPv4 アドレス（v1 では v6 は未対応）
//
// 使い方:
//   FIpAddress addr = FIpAddress::FromString("127.0.0.1");
//   FIpAddress any  = FIpAddress::Any();
//   FIpAddress lo   = FIpAddress::Loopback();
//   addr.port = 8080;


namespace acs {

/**
 * IPv4 アドレスとポートを保持する値型 (v1 では IPv6 未対応)。
 *
 * @details
 * octets[0..3] にドット区切り表記の各オクテットを格納し、port にポート番号を持つ。
 * 既定値は 0.0.0.0:0。Any()/Loopback()/FromString() で生成する。
 */
struct FIpAddress {
    /** ドット区切り表記の各オクテット (octets[0] が最上位)。既定 0.0.0.0。 */
    u8  octets[4] = {0, 0, 0, 0};

    /** ポート番号 (ホストバイトオーダ)。既定 0。 */
    u16 port      = 0;

    /**
     * 全インターフェイスを表す 0.0.0.0 を返す。
     *
     * @return octets が全 0、port が 0 の FIpAddress。
     */
    static FIpAddress Any() noexcept   { return FIpAddress{}; }

    /**
     * ループバックアドレス 127.0.0.1 を返す。
     *
     * @return 127.0.0.1 (port は 0) を表す FIpAddress。
     */
    static FIpAddress Loopback() noexcept {
        FIpAddress a;
        a.octets[0] = 127;
        a.octets[3] = 1;
        return a;
    }

    /**
     * "192.168.0.1" のようなドット区切り文字列から生成する。
     *
     * @details
     * 4 オクテットが揃わない、各値が 255 を超える、数字とドット以外の文字を含む、
     * といった不正な書式の場合は 0.0.0.0 を返す。port は設定しない。
     * @param dotted ドット区切りの IPv4 文字列 (nullptr の場合は 0.0.0.0 を返す)。
     * @return 解析した FIpAddress (不正なら 0.0.0.0)。
     */
    static FIpAddress FromString(const char* dotted) noexcept;
};

} // namespace acs

// ===================== network/Network.h =====================
// SPDX-License-Identifier: Apache-2.0
// ネットワークサブシステム初期化（WSAStartup ラッパ）
//
// 使い方: アプリ起動時に一度 FNetwork::Init() を呼ぶ。FApplication が
//         Audio/Network 系を自動初期化することは無いので、明示的に呼ぶこと。


namespace acs {

/** FNetwork が所有する Winsock 資源の診断スナップショット。 */
struct FNetworkDiagnostics {
    /** 現在の Init 参照数。 */
    u32 initialization_reference_count = 0;

    /** 再試行を待っている WSACleanup エラー。0 は保留なし。 */
    u32 pending_cleanup_error = 0;

    /** プロセス寿命中に観測した資源解放失敗の累積数。 */
    u64 resource_release_failure_count = 0;
};

/**
 * ネットワークサブシステムの初期化・終了を司る WSAStartup ラッパ。
 *
 * @details
 * 全メンバが static。多重 Init は内部の参照カウントで安全に扱い、最後の Shutdown で
 * 実際に WSACleanup を呼ぶ。FApplication は自動初期化しないので明示的に呼ぶこと。
 */
class FNetwork {
public:
    /**
     * WinSock を初期化する (多重呼び出し可)。
     *
     * @details
     * 内部の参照カウントと WSAStartup / WSACleanup を排他制御し、カウントが 0 の
     * ときだけ WSAStartup を呼ぶ。既に初期化済みなら参照数のみ +1 する。
     * @return 成功なら空の TResult、WSAStartup 失敗ならエラー。
     */
    static TResult<void> Init() noexcept;

    /**
     * 参照カウントを 1 減らし、最後の参照が外れたら WSACleanup を呼ぶ。
     *
     * @details カウントが 0 のときの呼び出しはアンダーフローを避けるため no-op。
     */
    static void Shutdown() noexcept;

    /**
     * 初期化済みかどうかを返す。
     *
     * @return 参照カウントが 1 以上なら true。
     */
    static bool IsInitialized() noexcept;

    /** 参照数・cleanup debt・資源解放失敗数を一貫した時点で取得する。 */
    static FNetworkDiagnostics CaptureDiagnostics() noexcept;
};

} // namespace acs

// ===================== network/TcpConnection.h =====================
// SPDX-License-Identifier: Apache-2.0
// TCP 接続（送信・受信）
//
// 使い方 (クライアント側):
//   auto cr = FTcpConnection::Connect(FIpAddress::FromString("127.0.0.1"), 8080);
//   if (cr.IsErr()) { ... }
//   FTcpConnection& c = cr.Value();
//   c.Send(data, size);
//   isize n = c.Recv(buf, sizeof(buf));


namespace acs {

/**
 * TCP ストリーム接続を表す single-owner なソケットハンドル。
 *
 * @details
 * クライアントは Connect で接続し、サーバ側は FTcpListener::Accept の戻り値から
 * FromAccepted 経由で構築される。Send/Recv でバイト列を送受信し、Close または
 * デストラクタで切断する。OS の SOCKET を単独所有する non-copy / move-only 型で、
 * 無効値は ~uptr{0} (=INVALID_SOCKET 相当) を用いる。
 */
class FTcpConnection {
public:
    /** 無効な (未接続の) 接続を構築する。 */
    FTcpConnection() noexcept = default;

    /** デストラクタ。接続が開いていれば Close で切断する。 */
    ~FTcpConnection() noexcept;

    /** コピー禁止 (ソケットを単独所有するため)。 */
    FTcpConnection(const FTcpConnection&) = delete;

    /** コピー代入も禁止。 */
    FTcpConnection& operator=(const FTcpConnection&) = delete;

    /**
     * ムーブ構築する。
     *
     * @details ソケットの所有権を移し、移動元は無効値 (~uptr{0}) になる。
     * @param o 移動元の接続。
     */
    FTcpConnection(FTcpConnection&& o) noexcept;

    /**
     * ムーブ代入する。
     *
     * @details 既存の接続を Close してから所有権を移し、移動元は無効値になる。
     *          自己代入は無視する。
     * @param o 移動元の接続。
     * @return 自身への参照。
     */
    FTcpConnection& operator=(FTcpConnection&& o) noexcept;

    /**
     * 指定アドレス・ポートへ TCP 接続する。
     *
     * @details
     * FNetwork::Init() が未呼出ならエラーを返す。socket → connect を行い、成功すれば
     * remote に port をセットした接続を返す。失敗時はソケットを閉じて OS エラーを返す。
     * @param addr 接続先 IP アドレス。
     * @param port 接続先ポート番号。
     * @return 接続済みの FTcpConnection、または接続失敗を表すエラー。
     */
    static TResult<FTcpConnection> Connect(FIpAddress addr, u16 port) noexcept;

    /**
     * 受理済みソケットから接続を構築する (内部用)。
     *
     * @details FTcpListener::Accept が受理した SOCKET と相手アドレスを受け取って包む。
     * @param socket 受理済みソケットハンドル。
     * @param remote 相手側の IP アドレス。
     * @return 受理済みソケットを所有する FTcpConnection。
     */
    static FTcpConnection FromAccepted(uptr socket, FIpAddress remote) noexcept;

    /**
     * 接続を切断する (多重呼び出し安全。デストラクタからも呼ばれる)。
     *
     * @details 開いていれば shutdown(SD_BOTH) → closesocket し、ソケットを無効値に戻す。
     */
    void Close() noexcept;

    /**
     * バッファを送信する。
     *
     * @details 部分送信があり得る (要求サイズより少ないことがある)。未接続またはエラー時は -1。
     * @param data 送信するデータの先頭ポインタ。
     * @param size 送信するバイト数。
     * @return 実際に送れたバイト数。失敗時は -1。
     */
    isize Send(const void* data, usize size) noexcept;

    /**
     * バッファへ受信する。
     *
     * @details 未接続またはエラー時は -1、相手が切断した場合は 0 を返す。
     * @param buf 受信先バッファの先頭ポインタ。
     * @param size 受信先バッファのバイト数。
     * @return 受信したバイト数 (0 は相手切断)。失敗時は -1。
     */
    isize Recv(void* buf, usize size) noexcept;

    /**
     * ソケットをノンブロッキング/ブロッキングモードに切り替える。
     *
     * @details ioctlsocket(FIONBIO) を使う。未接続または失敗時はエラーを返す。
     * @param enable true でノンブロッキング、false でブロッキング。
     * @return 成功なら空の TResult、失敗なら OS エラー。
     */
    TResult<void> SetNonBlocking(bool enable) noexcept;

    /**
     * 接続が有効 (ソケットが開いている) かを返す。
     *
     * @return 有効なら true。
     */
    bool      IsValid()  const noexcept { return m_Socket != ~uptr{0}; }

    /**
     * 相手側の IP アドレスを返す。
     *
     * @return 接続相手の FIpAddress。
     */
    FIpAddress Remote()   const noexcept { return m_Remote; }

private:
    /** OS のソケットハンドル (~uptr{0} を無効値とする)。 */
    uptr      m_Socket = ~uptr{0};

    /** 接続相手の IP アドレス。 */
    FIpAddress m_Remote {};
};

} // namespace acs

// ===================== network/TcpListener.h =====================
// SPDX-License-Identifier: Apache-2.0
// TCP リスナー（接続を待ち受ける側）
//
// 使い方 (サーバ側):
//   auto lr = FTcpListener::Listen(FIpAddress::Any(), 8080);
//   if (lr.IsErr()) { ... }
//   FTcpListener& l = lr.Value();
//   while (true) {
//       auto cr = l.Accept();
//       if (cr.IsOk()) HandleClient(Move(cr.Value()));
//   }


namespace acs {

/**
 * TCP 接続を待ち受けるリスナー (サーバ側)。
 *
 * @details
 * Listen() で bind/listen まで済んだソケットを生成し、Accept() で 1 接続ずつ
 * FTcpConnection を受け取る。ソケットを単独所有する non-copy / move-only 型で、
 * ムーブ後の元オブジェクトは無効状態 (m_Socket = ~uptr{0}) になる。
 */
class FTcpListener {
public:
    /** 無効状態 (ソケット未確保) で構築する。 */
    FTcpListener() noexcept = default;

    /** ソケットが開いていれば閉じてから破棄する。 */
    ~FTcpListener() noexcept;

    /** コピー禁止 (ソケットを単独所有するため)。 */
    FTcpListener(const FTcpListener&) = delete;

    /** コピー代入も禁止。 */
    FTcpListener& operator=(const FTcpListener&) = delete;

    /**
     * ムーブ構築する (ソケットの所有権を奪い、元を無効化する)。
     *
     * @param o ムーブ元のリスナー (実行後は無効状態になる)。
     */
    FTcpListener(FTcpListener&& o) noexcept;

    /**
     * ムーブ代入する (自分のソケットを閉じてから所有権を奪う)。
     *
     * @param o ムーブ元のリスナー (実行後は無効状態になる)。
     * @return *this への参照。
     */
    FTcpListener& operator=(FTcpListener&& o) noexcept;

    /**
     * 指定アドレス/ポートで Listen を開始する。
     *
     * @details
     * socket→SO_REUSEADDR→bind→listen を実行する。FNetwork::Init() 未呼び出し、
     * または各 WinSock 呼び出しの失敗時はエラーを返す。
     * @param addr バインドするアドレス (FIpAddress::Any() で全インターフェイス)。
     * @param port 待ち受けるポート番号。
     * @param backlog 接続キューの最大長 (既定 16)。
     * @return 成功なら待ち受け中の FTcpListener、失敗ならエラー。
     */
    static TResult<FTcpListener> Listen(FIpAddress addr, u16 port, u32 backlog = 16) noexcept;

    /**
     * 1 接続を受け付ける (ブロッキング)。
     *
     * @details accept した接続を FTcpConnection として返す。リモートのアドレス/ポートも設定される。
     * @return 成功なら受理した FTcpConnection、失敗ならエラー。
     */
    TResult<FTcpConnection> Accept() noexcept;

    /**
     * ソケットのノンブロッキングモードを切り替える。
     *
     * @param enable true でノンブロッキング、false でブロッキングにする。
     * @return 成功なら空の TResult、ioctlsocket 失敗ならエラー。
     */
    TResult<void> SetNonBlocking(bool enable) noexcept;

    /** ソケットが開いていれば閉じて無効状態にする (多重呼び出し安全)。 */
    void Close() noexcept;

    /**
     * 有効なソケットを保持しているかを返す。
     *
     * @return ソケットが開いていれば true。
     */
    bool IsValid() const noexcept { return m_Socket != ~uptr{0}; }

private:
    /** WinSock ソケットハンドル (~uptr{0} は無効)。 */
    uptr m_Socket = ~uptr{0};
};

} // namespace acs

// ===================== network/UdpSocket.h =====================
// SPDX-License-Identifier: Apache-2.0
// UDP ソケット（コネクションレス）
//
// 使い方:
//   auto sr = FUdpSocket::Bind(FIpAddress::Any(), 8080);
//   if (sr.IsErr()) { ... }
//   FUdpSocket& s = sr.Value();
//
//   FIpAddress from{};
//   isize n = s.RecvFrom(buf, sizeof(buf), from);
//
//   s.SendTo(FIpAddress::FromString("192.168.0.1"), 8080, data, size);


namespace acs {

/**
 * コネクションレスな UDP ソケット。
 *
 * @details
 * Bind() で生成し、SendTo()/RecvFrom() でデータグラムを送受信する。OS の
 * ソケットハンドルを単独所有する non-copy / move-only 型で、デストラクタや
 * Close() で確実にハンドルを閉じる。内部ハンドルは ~uptr{0} を無効値として持つ。
 */
class FUdpSocket {
public:
    /** 無効なソケット (ハンドル未確保) を構築する。 */
    FUdpSocket() noexcept = default;

    /** ソケットを閉じて破棄する。 */
    ~FUdpSocket() noexcept;

    /** コピー禁止 (OS ソケットハンドルを単独所有するため)。 */
    FUdpSocket(const FUdpSocket&) = delete;

    /** コピー代入も禁止。 */
    FUdpSocket& operator=(const FUdpSocket&) = delete;

    /**
     * ムーブ構築する (移動元のハンドルを奪い、移動元は無効化する)。
     *
     * @param o 移動元ソケット (ムーブ後は無効状態になる)。
     */
    FUdpSocket(FUdpSocket&& o) noexcept;

    /**
     * ムーブ代入する (自身の既存ハンドルを閉じてから移動元のハンドルを奪う)。
     *
     * @param o 移動元ソケット (ムーブ後は無効状態になる)。
     * @return 自身への参照。
     */
    FUdpSocket& operator=(FUdpSocket&& o) noexcept;

    /**
     * 指定アドレス/ポートにバインドした UDP ソケットを生成する。
     *
     * @details
     * 受信専用なら受信ポートを指定し、送信専用なら port=0 を渡して OS にポートを
     * 任せる。事前に FNetwork::Init() が呼ばれている必要がある。
     * @param addr バインドするローカルアドレス (Any() で全インターフェイス)。
     * @param port バインドするローカルポート (0 で OS 任せ)。
     * @return 成功なら生成した FUdpSocket、失敗ならエラー。
     */
    static TResult<FUdpSocket> Bind(FIpAddress addr, u16 port) noexcept;

    /**
     * 指定先へデータグラムを送信する。
     *
     * @param dst_addr 送信先 IPv4 アドレス。
     * @param dst_port 送信先ポート。
     * @param data 送信するデータの先頭。
     * @param size 送信するバイト数。
     * @return 送信できたバイト数、失敗時は -1。
     */
    isize SendTo(FIpAddress dst_addr, u16 dst_port, const void* data, usize size) noexcept;

    /**
     * データグラムを受信する。
     *
     * @param buf 受信データを書き込むバッファ。
     * @param size buf の容量 (バイト)。
     * @param from 送信元アドレス/ポートの書き込み先 (出力)。
     * @return 受信できたバイト数、失敗時は -1。
     */
    isize RecvFrom(void* buf, usize size, FIpAddress& from) noexcept;

    /**
     * ノンブロッキングモードを設定する。
     *
     * @param enable true でノンブロッキング、false でブロッキング。
     * @return 成功なら空の TResult、失敗ならエラー。
     */
    TResult<void> SetNonBlocking(bool enable) noexcept;

    /** ソケットを閉じてハンドルを無効化する (多重呼び出し安全)。 */
    void Close() noexcept;

    /**
     * 有効なソケットハンドルを保持しているかを返す。
     *
     * @return 有効なら true。
     */
    bool IsValid() const noexcept { return m_Socket != ~uptr{0}; }

private:
    /** OS ソケットハンドル (~uptr{0} は無効値)。 */
    uptr m_Socket = ~uptr{0};
};

} // namespace acs

// ===================== openxr/KhronosOpenXrBridge.h =====================
// SPDX-License-Identifier: Apache-2.0
// Real Khronos OpenXR loader backend for acs::game::IOpenXrBridge.


namespace acs::openxr {

/** OpenXR ランタイム未インストール時のエラー subcode。 */
inline constexpr acs::u16 kSubOpenXrRuntimeUnavailable = 301;

/** OpenXR instance 生成失敗時のエラー subcode。 */
inline constexpr acs::u16 kSubOpenXrInitFailed         = 302;

/**
 * Khronos OpenXR loader をバックエンドとする IOpenXrBridge の実装。
 *
 * @details
 * Init() で xrEnumerateInstanceExtensionProperties / xrCreateInstance を呼び、
 * loader/instance seam だけを所有する。session loop (xrCreateSession +
 * frame/view/action loop) は graphics binding と HMD ランタイムを要求するため本
 * backend では未実装で、HeadPose()/LeftController()/RightController() は常に原点
 * (未トラッキングのゼロポーズ) を返し IsTracking() は常に false を返す。passthrough
 * 拡張 (XR_FB_passthrough / XR_HTC_passthrough) の有無のみ検出する。
 */
class FKhronosOpenXrBridge final : public acs::game::IOpenXrBridge {
public:
    /** 空状態で構築する (instance は Init で生成)。 */
    FKhronosOpenXrBridge() noexcept = default;

    /** 破棄する (Shutdown を呼んで instance を解放)。 */
    ~FKhronosOpenXrBridge() noexcept override;

    /**
     * OpenXR instance を生成して backend を初期化する。
     *
     * @details
     * 既に初期化済みなら何もせず成功を返す。ランタイム未インストールなら
     * kSubOpenXrRuntimeUnavailable、instance 生成失敗なら kSubOpenXrInitFailed の
     * エラーを返す。session は生成しないため、成功しても実トラッキングは始まらない。
     * @param platform 接続先プラットフォーム (記録するのみで自動検出には使わない)。
     * @return 成功なら空の TResult、失敗ならエラー。
     */
    acs::TResult<void> Init(acs::game::EXrPlatform platform = acs::game::EXrPlatform::Unknown) noexcept override;

    /** instance を破棄し全状態をゼロへ戻す (Init 前に呼んでも安全)。 */
    void Shutdown() noexcept override;

    /**
     * 初期化済みかを返す。
     *
     * @return Init() 成功後かつ Shutdown() 前なら true。
     */
    bool IsInitialized() const noexcept override { return m_bInitialized; }

    /**
     * 記録された backend プラットフォームを返す。
     *
     * @return Init() で渡されたプラットフォーム (未初期化なら Unknown)。
     */
    acs::game::EXrPlatform ActivePlatform() const noexcept override { return m_Platform; }

    /**
     * 直近 Tick 時点の HMD ポーズを返す。
     *
     * @return HMD ポーズ (session 未実装のため常に原点ゼロポーズ)。
     */
    acs::game::FXrPose HeadPose() const noexcept override { return m_HeadPose; }

    /**
     * 直近 Tick 時点の左コントローラ state を返す。
     *
     * @return 左コントローラ state (session 未実装のため常にゼロ state)。
     */
    acs::game::FXrControllerState LeftController() const noexcept override { return m_Left; }

    /**
     * 直近 Tick 時点の右コントローラ state を返す。
     *
     * @return 右コントローラ state (session 未実装のため常にゼロ state)。
     */
    acs::game::FXrControllerState RightController() const noexcept override { return m_Right; }

    /**
     * ポーズ / 入力の取り込みを進める。
     *
     * @details
     * session loop が未実装のため実トラッキングは行わず、初期化済みなら一度だけ未実装の
     * 警告ログを出し、HeadPose / 左右コントローラを毎フレーム原点ゼロポーズへ保つ。
     * @param dt 実時間の経過秒 (本 backend では使わない)。
     */
    void Tick(acs::f32 dt) noexcept override;

    /**
     * passthrough (MR モード) をサポートするかを返す。
     *
     * @return Init 時に XR_FB_passthrough / XR_HTC_passthrough を検出していれば true。
     */
    bool IsPassthroughSupported() const noexcept override { return m_bPassthroughSupported; }

    /**
     * passthrough の on/off を要求する。
     *
     * @details サポートされている場合のみ要求フラグを更新する (非対応なら常に無効のまま)。
     * @param b_on true で passthrough を有効化、false で無効化。
     */
    void SetPassthrough(bool b_on) noexcept override;

    /**
     * 実トラッキングが生きているかを返す。
     *
     * @details
     * 本 backend は loader/instance seam のみを所有し session loop は未実装なので、
     * 現状は常に false を返す。HeadPose()/LeftController()/RightController() が返す
     * ゼロポーズを「有効なトラッキング値」と誤認しないために、消費側 (IOpenXrBridge&
     * 越しも含む) はこのフラグを見て fallback を選ぶこと。
     * @return 実トラッキング中なら true (本 backend では常に false)。
     */
    bool IsTracking() const noexcept override { return m_bSessionTracking; }

private:
    /** XrInstance (公開 header の TU では opaque に保つ)。 */
    void* m_Instance = nullptr;

    /** 直近 Tick の HMD ポーズ (session 未実装のため常に原点)。 */
    acs::game::FXrPose m_HeadPose{};

    /** 直近 Tick の左コントローラ state。 */
    acs::game::FXrControllerState m_Left{};

    /** 直近 Tick の右コントローラ state。 */
    acs::game::FXrControllerState m_Right{};

    /** Init で記録されたプラットフォーム。 */
    acs::game::EXrPlatform m_Platform = acs::game::EXrPlatform::Unknown;

    /** 初期化済みフラグ (instance 生成成功で true)。 */
    bool m_bInitialized = false;

    /** passthrough 拡張が利用可能かどうか。 */
    bool m_bPassthroughSupported = false;

    /** passthrough の有効化が要求されているかどうか。 */
    bool m_bPassthroughRequested = false;

    /**
     * 実セッションが確立してポーズが更新されているか。
     *
     * @details session loop は本 TU では未実装なので常に false。
     */
    bool m_bSessionTracking = false;

    /** Tick() の「session loop 未実装」警告を一度だけ出すためのラッチ。 */
    bool m_bTickWarned = false;
};

/**
 * プロセス共有 singleton の実 Khronos bridge を返す。
 *
 * @details
 * 初回アクセス時に Init() を 1 回走らせる (失敗しても参照は返すので、呼び出し側は
 * IsInitialized() を見て fallback を判断する)。
 * @return プロセス共有の実 Khronos OpenXR bridge への参照。
 */
acs::game::IOpenXrBridge& GetDefaultKhronosOpenXrBridge() noexcept;

/**
 * gameframework の既定 provider に GetDefaultKhronosOpenXrBridge を登録する。
 *
 * @details
 * gameframework は本モジュール (ACS::OpenXr) に依存できない (循環依存) ため、結線は
 * backend 側 (本モジュール) から acs::game::SetOpenXrBridgeProvider() を呼んで行う。
 * アプリは起動時に一度これを呼ぶだけで、以降は backend 非依存に
 * acs::game::GetDefaultOpenXrBridge() で実 Khronos OpenXR bridge を取得できる。
 */
void InstallOpenXrAsDefault() noexcept;

} // namespace acs::openxr

// ===================== platform/FileSystem.h =====================
// SPDX-License-Identifier: Apache-2.0
// ファイル I/O とパス操作
//
// 使い方:
//   auto data = FFileSystem::ReadAllBytes(L"data/save.bin");
//   if (data.IsErr()) { /* エラー処理 */ }
//   TSpan<const byte> bytes = data.Value().AsSpan();
//
//   FFileSystem::WriteAllBytes(L"data/save.bin", bytes);


namespace acs {

/** ファイル I/O とパス操作のユーティリティ (全メソッド static、Win32 実装)。 */
class FFileSystem {
public:
    /**
     * ファイル全体をバイト列として読み込む。
     *
     * @details 4GB を超えるファイルはエラー。OPEN_EXISTING で開くため未存在は失敗。
     * @param path 読み込むファイルのパス。
     * @return 読み込んだバイト列、開けない・サイズ過大・読み取り失敗時はエラー。
     */
    static TResult<TArray<byte>> ReadAllBytes(const wchar_t* path) noexcept;

    /**
     * ファイル全体を文字列として読み込む。
     *
     * @details ReadAllBytes の結果に末尾 NUL を付与して返す (中身は無変換のバイト列)。
     * @param path 読み込むファイルのパス。
     * @return NUL 終端付きの文字配列、読み取り失敗時はエラー。
     */
    static TResult<TArray<char>> ReadAllText(const wchar_t* path) noexcept;

    /**
     * バイト列をファイルへ書き出す (既存ファイルは上書き)。
     *
     * @details CREATE_ALWAYS で開くため既存内容は破棄される。
     * @param path 書き出し先のファイルパス。
     * @param data 書き出すバイト列の先頭。
     * @param size 書き出すバイト数。
     * @return 成功なら空の TResult、開けない・書き込み不足時はエラー。
     */
    static TResult<void> WriteAllBytes(const wchar_t* path, const byte* data, usize size) noexcept;

    /**
     * NUL 終端文字列をファイルへ書き出す (終端 NUL は書き込まない)。
     *
     * @param path 書き出し先のファイルパス。
     * @param text 書き出す NUL 終端文字列 (nullptr は長さ 0 扱い)。
     * @return 成功なら空の TResult、書き込み失敗時はエラー。
     */
    static TResult<void> WriteAllText(const wchar_t* path, const char* text) noexcept;

    /**
     * ファイルサイズをバイト単位で取得する。
     *
     * @param path 対象ファイルのパス。
     * @return ファイルサイズ (byte)、属性取得失敗時はエラー。
     */
    static TResult<u64> FileSize(const wchar_t* path) noexcept;

    /**
     * 指定パスがファイルとして存在するかを返す。
     *
     * @param path 確認するパス。
     * @return 存在しディレクトリでなければ true。
     */
    static bool Exists(const wchar_t* path) noexcept;

    /**
     * 指定パスがディレクトリとして存在するかを返す。
     *
     * @param path 確認するパス。
     * @return 存在しディレクトリなら true。
     */
    static bool DirectoryExists(const wchar_t* path) noexcept;

    /**
     * ディレクトリを作成する (既存なら成功扱い、親ディレクトリも再帰作成)。
     *
     * @details パス中の各区切りで中間ディレクトリを順に作成する。最終作成が
     * ERROR_ALREADY_EXISTS の場合も成功とみなす。
     * @param path 作成するディレクトリのパス。
     * @return 成功なら空の TResult、作成失敗時はエラー。
     */
    static TResult<void> CreateDirectory(const wchar_t* path) noexcept;

    /**
     * ファイルを削除する。
     *
     * @param path 削除するファイルのパス。
     * @return 成功なら空の TResult、削除失敗時はエラー。
     */
    static TResult<void> Delete(const wchar_t* path) noexcept;
};

} // namespace acs

// ===================== platform/Input.h =====================
// SPDX-License-Identifier: Apache-2.0
// 入力ポーリング API（キーボード / マウス / ゲームパッド）
//
// 使い方:
//   while (!w.ShouldClose()) {
//       FInput::Update();           // フレーム先頭で呼ぶ
//       w.PollEvents();
//
//       if (FInput::IsKeyDown(EKey::Space)) Jump();
//       if (FInput::IsMouseButtonPressed(EMouseButton::Left)) Shoot();
//       FVec2 m = FInput::MousePos();
//   }
//
// ・「Down」 = 現在押されている
// ・「Pressed」 = このフレームで押された (前フレームは Down ではなかった)
// ・「Released」 = このフレームで離された


namespace acs {

/**
 * キーボード・マウス・ゲームパッドの入力ポーリング API (全メソッド static)。
 *
 * @details
 * 状態はプロセス唯一のグローバルに保持する。フレーム先頭で Update を呼んで現フレームと
 * 前フレームを進め、FWindow からのイベントを OnEvent でこの状態へ反映する。「Down」=現在
 * 押下中、「Pressed」=このフレームで押下開始、「Released」=このフレームで離した、を表す。
 */
class FInput {
public:
    /**
     * フレーム先頭で 1 回呼び、入力状態をフレーム間で進める。
     *
     * @details 現フレームの押下状態を前フレームへ移し、マウス差分・ホイール累積を確定し、
     * テキスト入力をクリアし、XInput を 4 ポート分ポーリングする。
     */
    static void Update() noexcept;

    /**
     * FWindow から受け取ったイベントを入力状態へ反映する。
     *
     * @details FWindow::SetEventCallback でこの関数へブリッジして使う。
     * @param e 反映するイベント。
     */
    static void OnEvent(const FEvent& e) noexcept;

    /**
     * キーが現在押されているかを返す。
     *
     * @param k 対象キー。
     * @return 押下中なら true。
     */
    static bool IsKeyDown(EKey k) noexcept;

    /**
     * キーがこのフレームで押下開始されたかを返す。
     *
     * @param k 対象キー。
     * @return 前フレームは離されていて今フレームで押されたなら true。
     */
    static bool IsKeyPressed(EKey k) noexcept;

    /**
     * キーがこのフレームで離されたかを返す。
     *
     * @param k 対象キー。
     * @return 前フレームは押されていて今フレームで離されたなら true。
     */
    static bool IsKeyReleased(EKey k) noexcept;

    /**
     * マウスボタンが現在押されているかを返す。
     *
     * @param b 対象ボタン。
     * @return 押下中なら true。
     */
    static bool IsMouseButtonDown(EMouseButton b) noexcept;

    /**
     * マウスボタンがこのフレームで押下開始されたかを返す。
     *
     * @param b 対象ボタン。
     * @return 前フレームは離されていて今フレームで押されたなら true。
     */
    static bool IsMouseButtonPressed(EMouseButton b) noexcept;

    /**
     * マウスボタンがこのフレームで離されたかを返す。
     *
     * @param b 対象ボタン。
     * @return 前フレームは押されていて今フレームで離されたなら true。
     */
    static bool IsMouseButtonReleased(EMouseButton b) noexcept;

    /**
     * マウスカーソルの現在位置を返す。
     *
     * @return クライアント座標での位置 (px)。
     */
    static FVec2 MousePos() noexcept;

    /**
     * 前フレームからのマウス移動量を返す。
     *
     * @return クライアント座標での差分 (px)。
     */
    static FVec2 MouseDelta() noexcept;

    /**
     * このフレームのマウスホイール回転量を返す。
     *
     * @return ノッチ数 (正=奥へ回転、負=手前へ回転)。
     */
    static f32  MouseWheel() noexcept;

    /**
     * このフレームに入力されたテキストを返す。
     *
     * @details IME 確定後の UTF-8 文字列。次の Update でクリアされる内部バッファを指す。
     * @return NUL 終端の UTF-8 文字列 (入力が無ければ空文字列)。
     */
    static const char* TextInput() noexcept;

    /**
     * 指定プレイヤーのゲームパッドが接続されているかを返す。
     *
     * @param player_index プレイヤー番号 (0..3)。
     * @return 直近の Update で接続が確認できれば true (範囲外は false)。
     */
    static bool IsGamepadConnected(u32 player_index) noexcept;

    /**
     * 指定プレイヤーのゲームパッドボタンが現在押されているかを返す。
     *
     * @param player_index プレイヤー番号 (0..3)。
     * @param b 対象ボタン。
     * @return 押下中なら true (未接続・範囲外・Guide ボタンは false)。
     */
    static bool IsGamepadButtonDown(u32 player_index, EGamepadButton b) noexcept;

    /**
     * 指定プレイヤーのゲームパッドボタンがこのフレームで押下開始されたかを返す。
     *
     * @param player_index プレイヤー番号 (0..3)。
     * @param b 対象ボタン。
     * @return 前フレームは離されていて今フレームで押されたなら true (未接続・範囲外は false)。
     */
    static bool IsGamepadButtonPressed(u32 player_index, EGamepadButton b) noexcept;

    /**
     * 指定プレイヤーのゲームパッドボタンがこのフレームで解放されたかを返す。
     *
     * @details 押下中にゲームパッドが切断された場合も、一度だけ解放として扱う。
     * @param player_index プレイヤー番号 (0..3)。
     * @param b 対象ボタン。
     * @return 前フレームは押されていて今フレームで離されたなら true。
     */
    static bool IsGamepadButtonReleased(u32 player_index, EGamepadButton b) noexcept;

    /**
     * 指定プレイヤーのゲームパッド軸の値を返す。
     *
     * @details スティックはデッドゾーン処理込みで -1.0〜+1.0、トリガーは 0.0〜1.0 に正規化。
     * @param player_index プレイヤー番号 (0..3)。
     * @param axis 対象の軸。
     * @return 正規化された軸の値 (未接続・範囲外は 0.0)。
     */
    static f32  GamepadAxisValue(u32 player_index, EGamepadAxis axis) noexcept;
};

} // namespace acs

// ===================== platform/Localization.h =====================
// SPDX-License-Identifier: Apache-2.0
// 多言語対応（i18n）
//
// 設計:
//   - 各言語は INI 形式の FStorage（key=value、UTF-8）
//   - active = 現在表示中の言語、fallback = キーが無い時の代替
//   - FStorage を直接利用するので、ファイル形式 / 内部構造を学び直す必要なし
//
// 使い方:
//   FLocalization L;
//   L.LoadActive(L"lang/ja.lang");
//   L.LoadFallback(L"lang/en.lang");
//
//   FRenderer 内:
//     sb.DrawText(font, L.Tr("greeting"), 100, 100, color);
//
//   ja.lang 内容例:
//     # コメント
//     greeting=ハロー、世界！
//     menu.start=ゲーム開始
//     menu.exit=終了
//
//   en.lang 内容例:
//     greeting=Hello, World!
//     menu.start=Start Game
//     menu.exit=Quit
//
// 言語切替:
//   L.LoadActive(L"lang/de.lang");   // 別言語に切替（fallback はそのまま）


// ===================== platform/Storage.h =====================
// SPDX-License-Identifier: Apache-2.0
// 設定 / セーブデータ用 key-value ストア（INI 形式）
//
// 用途: ゲーム設定（音量・解像度）、セーブデータ（ハイスコア・進行度）の
//       人間可読な永続化。
//
// 使い方:
//   FStorage cfg;
//   wchar_t path[260];
//   FStorage::GetAppDataPath(L"MyGame", L"settings.ini", path, 260);
//
//   cfg.Load(path);                       // 既存があれば読み込む（無ければ空）
//   if (!cfg.Has("master_volume")) {
//       cfg.SetFloat("master_volume", 0.8f);
//   }
//   f64 vol = cfg.GetFloat("master_volume", 0.8);
//   cfg.SetInt("high_score", 12345);
//   cfg.Save(path);                       // 保存
//
// ファイル形式 (INI 風、フラット):
//   master_volume=0.8
//   resolution_w=1920
//   high_score=12345
//   player_name=タロウ
//
// セクションは v1 では持たず、平坦なキー名（例 "audio.master_volume"）で
// 名前空間分けする想定。


namespace acs {

/**
 * 設定・セーブデータ用の key-value ストア (INI 風、フラット、UTF-8)。
 *
 * @details
 * key=value の平坦なエントリ列を保持し、ファイル/バイト列との間で読み書きする。セクションは
 * 持たず、"audio.master_volume" のような点区切りキーで名前空間を分ける想定。値は内部で文字列
 * として保持し、Int/Float/Bool は文字列との相互変換で扱う。non-copy・move-only。
 */
class FStorage {
public:
    /** DefaultAllocator を確保元として空のストアを構築する。 */
    FStorage() noexcept : FStorage(DefaultAllocator())
    {
    }

    /** 指定した allocator を全エントリの確保元として空のストアを構築する。 */
    explicit FStorage(FAllocator& allocator) noexcept : m_Entries(allocator), m_Allocator(&allocator)
    {
    }

    /** ストアを破棄する (エントリは TArray が解放)。 */
    ~FStorage() noexcept = default;

    /** コピー禁止 (エントリ配列を単独所有するため)。 */
    FStorage(const FStorage&)            = delete;

    /** コピー代入も禁止。 */
    FStorage& operator=(const FStorage&) = delete;

    /**
     * ムーブ構築する (エントリ配列の所有権を奪う。FLocalization::Swap 等で使う)。
     *
     * @param o ムーブ元 (奪われて空になる)。
     */
    FStorage(FStorage&& o) noexcept : m_Entries(Move(o.m_Entries)), m_Allocator(o.m_Allocator)
    {
    }

    /**
     * ムーブ代入する (エントリ配列の所有権を奪う)。
     *
     * @param o ムーブ元 (奪われて空になる)。
     * @return 自身への参照。
     */
    FStorage& operator=(FStorage&& o) noexcept {
        if (this != &o) {
            m_Entries = Move(o.m_Entries);
            m_Allocator = o.m_Allocator;
        }
        return *this;
    }

    /**
     * INI 形式ファイルから読み込む (wchar_t パス版)。
     *
     * @details ファイルが存在しなければ空のまま成功扱い。既存エントリは置き換わる。
     * @param path 読み込むファイルのパス。
     * @return 成功なら空の TResult、null パスや読み取り失敗時はエラー。
     */
    TResult<void> Load(const wchar_t* path) noexcept;

    /**
     * INI 形式ファイルから読み込む (UTF-8 パス版)。
     *
     * @details MultiByteToWideChar で wchar_t 版へ委譲する。
     * @param path_utf8 読み込むファイルの UTF-8 パス。
     * @return 成功なら空の TResult、変換失敗や読み取り失敗時はエラー。
     */
    TResult<void> Load(const char*    path_utf8) noexcept;

    /**
     * INI 形式 (UTF-8、改行区切り) のバイト列から読み込む。
     *
     * @details 実行ファイル埋め込みデータ等を直接読む用途。先頭の UTF-8 BOM はスキップし、
     * '#'/';'/'[' 始まりの行とキーのない行は無視する。'=' より後ろは先頭空白も値として
     * そのまま保持する。既存エントリはクリアされる。
     * @param data INI テキストの先頭 (nullptr は空扱いで成功)。
     * @param size data のバイト数。
     * @return 成功なら空の TResult。
     */
    // 同一キーは拒否し、解析・確保に失敗した場合は読み込み前の状態を保持する。
    TResult<void> LoadFromBytes(const u8* data, usize size) noexcept;

    /**
     * INI 形式ファイルへ保存する (wchar_t パス版)。
     *
     * @details 親ディレクトリが無ければ作成する。
     * @param path 保存先のファイルパス。
     * @return 成功なら空の TResult、null パスやディレクトリ作成・書き込み失敗時はエラー。
     */
    TResult<void> Save(const wchar_t* path) noexcept;

    /**
     * INI 形式ファイルへ保存する (UTF-8 パス版)。
     *
     * @details MultiByteToWideChar で wchar_t 版へ委譲する。
     * @param path_utf8 保存先の UTF-8 パス。
     * @return 成功なら空の TResult、変換失敗や書き込み失敗時はエラー。
     */
    TResult<void> Save(const char*    path_utf8) noexcept;

    /** 全エントリと予約容量を解放する (ファイルは触らない)。 */
    void Clear() noexcept
    {
        m_Entries = TArray<FEntry>(*m_Allocator);
    }

    /**
     * 文字列値を設定し、確保失敗時は既存状態を維持する。
     *
     * @param key 設定するキー (nullptr は拒否)。
     * @param value 設定する値 (nullptr は空文字列扱い)。
     * @return 設定できた場合は true。入力不正または確保失敗時は false。
     */
    bool TrySetString(const char* key, const char* value) noexcept
    {
        if (!key) return false;

        FEntry* entry = FindEntry(key);
        FString candidateValue(*m_Allocator);
        if (!candidateValue.TryAppend(
                FStringView(value ? value : ""))) {
            return false;
        }
        if (entry) {
            entry->value = Move(candidateValue);
            return true;
        }

        FString candidateKey(*m_Allocator);
        if (!candidateKey.TryAppend(FStringView(key))) return false;
        FEntry candidate;
        candidate.key = Move(candidateKey);
        candidate.value = Move(candidateValue);
        return m_Entries.TryPushBack(Move(candidate));
    }

    /**
     * 文字列値を設定する (既存キーは上書き)。
     *
     * @param key 設定するキー (nullptr は無視)。
     * @param value 設定する値 (nullptr は空文字列扱い)。
     */
    void SetString(const char* key, const char* value) noexcept;

    /**
     * 整数値を設定する (内部では十進文字列として保持)。
     *
     * @param key 設定するキー。
     * @param value 設定する整数値。
     */
    void SetInt   (const char* key, i64 value) noexcept;

    /**
     * 浮動小数点値を設定する (内部では往復可能な精度の文字列として保持)。
     *
     * @param key 設定するキー。
     * @param value 設定する値。
     */
    void SetFloat (const char* key, f64 value) noexcept;

    /**
     * 真偽値を設定する ("true"/"false" として保持)。
     *
     * @param key 設定するキー。
     * @param value 設定する真偽値。
     */
    void SetBool  (const char* key, bool value) noexcept;

    /**
     * 文字列値を取得する。
     *
     * @details 戻り値は内部バッファへの参照で、次の Set / Load で無効化されうる。長期保持する
     * 場合は呼び出し側でコピーすること。
     * @param key 取得するキー。
     * @param default_v キーが無いときに返す既定値。
     * @return 値への参照、無ければ default_v。
     */
    const char* GetString(const char* key, const char* default_v = "") const noexcept;

    /**
     * 整数値を取得する。
     *
     * @param key 取得するキー。
     * @param default_v キーが無いときに返す既定値。
     * @return 値を十進解釈した整数、無ければ default_v。
     */
    i64         GetInt   (const char* key, i64 default_v = 0) const noexcept;

    /**
     * 浮動小数点値を取得する。
     *
     * @param key 取得するキー。
     * @param default_v キーが無いときに返す既定値。
     * @return 値を解釈した実数、無ければ default_v。
     */
    f64         GetFloat (const char* key, f64 default_v = 0.0) const noexcept;

    /**
     * 真偽値を取得する。
     *
     * @details "true"/"1"/"yes"/"on" を真、"false"/"0"/"no"/"off" を偽と解釈する。
     * @param key 取得するキー。
     * @param default_v キーが無い・解釈不能なときに返す既定値。
     * @return 解釈した真偽値、該当しなければ default_v。
     */
    bool        GetBool  (const char* key, bool default_v = false) const noexcept;

    /**
     * キーが存在するかを返す。
     *
     * @param key 確認するキー。
     * @return 存在すれば true。
     */
    bool Has(const char* key) const noexcept;

    /**
     * キーとその値を削除する (順序は保証しない)。
     *
     * @param key 削除するキー (nullptr や未存在は何もしない)。
     */
    void Remove(const char* key) noexcept;

    /**
     * 保持しているエントリ数を返す。
     *
     * @return エントリ数。
     */
    usize Count() const noexcept { return m_Entries.Size(); }

    /**
     * %APPDATA%/<sub_dir>/<file_name> へのフルパスを構築する (wchar_t 版)。
     *
     * @details FOLDERID_RoamingAppData を起点に連結し、親ディレクトリ
     * (%APPDATA%/<sub_dir>) を自動作成する。
     * @param sub_dir サブディレクトリ名 (nullptr なら "acs")。
     * @param file_name ファイル名 (nullptr なら "storage.ini")。
     * @param out パスを書き込む先のバッファ。
     * @param cap out の容量 (要素数)。
     * @return 成功なら空の TResult、引数不正・既知フォルダ取得失敗・作成失敗時はエラー。
     */
    static TResult<void> GetAppDataPath(const wchar_t* sub_dir,
                                       const wchar_t* file_name,
                                       wchar_t* out, usize cap) noexcept;

    /**
     * %APPDATA%/<sub_dir>/<file_name> へのフルパスを構築する (UTF-8 版)。
     *
     * @details 引数を MultiByteToWideChar で変換し wchar_t 版へ委譲、結果を UTF-8 に戻す。
     * @param sub_dir_utf8 サブディレクトリ名 (UTF-8、nullptr 可)。
     * @param file_name_utf8 ファイル名 (UTF-8、nullptr 可)。
     * @param out_utf8 パスを書き込む先の UTF-8 バッファ。
     * @param cap out_utf8 の容量 (バイト数)。
     * @return 成功なら空の TResult、引数不正や変換失敗時はエラー。
     */
    static TResult<void> GetAppDataPath(const char* sub_dir_utf8,
                                       const char* file_name_utf8,
                                       char* out_utf8, usize cap) noexcept;

private:
    /** 1 件の key-value エントリ。 */
    struct FEntry {
        /** エントリのキー。 */
        FString key;

        /** エントリの値 (文字列として保持)。 */
        FString value;
    };

    /**
     * キーに一致するエントリを線形探索する (可変版)。
     *
     * @param key 探すキー。
     * @return 見つかったエントリ、無ければ nullptr。
     */
    FEntry*       FindEntry(const char* key) noexcept;

    /**
     * キーに一致するエントリを線形探索する (const 版)。
     *
     * @param key 探すキー。
     * @return 見つかったエントリ、無ければ nullptr。
     */
    const FEntry* FindEntry(const char* key) const noexcept;

    /** 保持している全エントリ。 */
    TArray<FEntry> m_Entries;

    /** エントリ配列と key/value 文字列を確保した allocator。 */
    FAllocator* m_Allocator = nullptr;
};

} // namespace acs

namespace acs {

/**
 * 多言語対応 (i18n) のための翻訳テーブル。
 *
 * @details
 * active (現在表示中) と fallback (代替) の 2 つの FStorage を持ち、Tr で active → fallback →
 * キー自体の順に解決する。各言語は INI 形式 (key=value、UTF-8) の FStorage として読み込む。
 * コピー禁止。
 */
class FLocalization {
public:
    /** 空の翻訳テーブルを構築する。 */
    FLocalization() noexcept = default;

    /** コピー禁止 (内部 FStorage が move-only のため)。 */
    FLocalization(const FLocalization&)            = delete;

    /** コピー代入も禁止。 */
    FLocalization& operator=(const FLocalization&) = delete;

    /**
     * 現在表示中の言語をファイルから読み込む。
     *
     * @param path 言語ファイル (INI 形式) のパス。
     * @return FStorage::Load の結果。
     */
    TResult<void> LoadActive  (const wchar_t* path) noexcept { return m_Active.Load(path); }

    /**
     * 代替 (fallback) 言語をファイルから読み込む。
     *
     * @param path 言語ファイル (INI 形式) のパス。
     * @return FStorage::Load の結果。
     */
    TResult<void> LoadFallback(const wchar_t* path) noexcept { return m_Fallback.Load(path); }

    /**
     * 現在表示中の言語をバイト列から読み込む (埋め込み用)。
     *
     * @param data INI テキストの先頭。
     * @param size data のバイト数。
     * @return FStorage::LoadFromBytes の結果。
     */
    TResult<void> LoadActiveBytes  (const u8* data, usize size) noexcept { return m_Active.LoadFromBytes(data, size); }

    /**
     * 代替 (fallback) 言語をバイト列から読み込む (埋め込み用)。
     *
     * @param data INI テキストの先頭。
     * @param size data のバイト数。
     * @return FStorage::LoadFromBytes の結果。
     */
    TResult<void> LoadFallbackBytes(const u8* data, usize size) noexcept { return m_Fallback.LoadFromBytes(data, size); }

    /** active と fallback を入れ替える (言語切替の便利関数)。 */
    void Swap() noexcept;

    /** active・fallback の全エントリを削除する。 */
    void Clear() noexcept { m_Active.Clear(); m_Fallback.Clear(); }

    /**
     * キーに対応する翻訳文字列を取得する。
     *
     * @details active → fallback → キー自体 (最後の手段) の順で探す。
     * @param key 翻訳キー (nullptr なら空文字列)。
     * @return 見つかった訳文、無ければ key 自体。
     */
    const char* Tr(const char* key) const noexcept;

    /**
     * キーが active か fallback のどちらかに存在するかを返す。
     *
     * @param key 確認するキー (nullptr は false)。
     * @return いずれかに存在すれば true。
     */
    bool Has(const char* key) const noexcept;

    /**
     * active 言語の FStorage への可変参照を返す (独自加工用)。
     *
     * @return active FStorage への参照。
     */
    FStorage&       Active()         noexcept { return m_Active; }

    /**
     * active 言語の FStorage への const 参照を返す。
     *
     * @return active FStorage への const 参照。
     */
    const FStorage& Active()   const noexcept { return m_Active; }

    /**
     * fallback 言語の FStorage への可変参照を返す (独自加工用)。
     *
     * @return fallback FStorage への参照。
     */
    FStorage&       Fallback()       noexcept { return m_Fallback; }

    /**
     * fallback 言語の FStorage への const 参照を返す。
     *
     * @return fallback FStorage への const 参照。
     */
    const FStorage& Fallback() const noexcept { return m_Fallback; }

private:
    /** 現在表示中の言語の翻訳テーブル。 */
    FStorage m_Active;

    /** キーが active に無いときに参照する代替言語の翻訳テーブル。 */
    FStorage m_Fallback;
};

} // namespace acs

// ===================== render/Atmosphere.h =====================
// SPDX-License-Identifier: Apache-2.0
// Physical atmospheric scattering (Hillaire 2020 / Bruneton 風)
//
// Rayleigh + Mie 単散乱を per-direction で CPU 評価し equirect 画像に焼く。
// `FImageBasedLighting::LoadEquirectHdrFromMemory` に通せば env cubemap →
// irradiance → prefilter の IBL chain が一気に物理ベースの sky で構築される。
//
// 物理パラメータ (Earth、Bruneton 2008):
//   - 地表半径 6360 km、大気上端 6420 km (厚さ 60 km)
//   - Rayleigh: β = (5.802, 13.558, 33.1) ×10⁻⁶ m⁻¹、scale height 8 km
//   - Mie:      β = 3.996 ×10⁻⁶ m⁻¹、absorption 4.4 ×10⁻⁶ m⁻¹、scale height 1.2 km、g=0.8
//
// 簡易: 単散乱のみ (multi-scatter / aerial perspective / ozone は未含)。


namespace acs {

/** Camera-volume quality contract shared by allocation and validation. */
inline constexpr u32 kSkyAtmosphereFroxelXyResolution = 48u;
inline constexpr u32 kSkyAtmosphereFroxelZResolution = 96u;
inline constexpr u32 kSkyAtmosphereFroxelIntegrationSteps = 24u;
/** Near-field range reserved for the dedicated local-fog froxel volume. */
inline constexpr f32 kLocalVolumetricFogMaxDistance = 2500.0f;

/**
 * 大気散乱 bake の入力パラメータ (太陽方向・強度とサンプル数)。
 *
 * @details
 * sun_dir は天頂方向 +Y を基準とした太陽方角で、正規化されていなくてもよい
 * (BakeEquirect 内で正規化される)。ray_steps / sun_steps は単散乱積分の精度と
 * コストのトレードオフを決める。
 */
struct FAtmosphereParams {
    /** 太陽方角 (天頂方向 +Y、正規化前提だが内部で再正規化される)。 */
    FVec3 sun_dir       = FVec3{0.4f, 0.7f, 0.4f};

    /** 太陽のピーク輝度 (W/m²/sr 相当)。 */
    FVec3 sun_intensity = FVec3{22.0f, 22.0f, 22.0f};

    /** Lambert ground と ground bounce に使う RGB アルベド。 */
    FVec3 ground_albedo = FVec3{0.10f, 0.12f, 0.10f};

    /** view ray 沿いのサンプル数。 */
    u32  ray_steps     = 32;

    /** 各 sample から sun への光線 (透過率) でのサンプル数。 */
    u32  sun_steps     = 8;
};

/**
 * camera-volume LUT に統合するローカル height fog。
 *
 * @details density=0 ならローカル fog は無効で、大気の aerial perspective のみを積分する。
 * density は scene 単位あたりの extinction。色は単散乱 albedo、anisotropy は
 * Henyey-Greenstein 位相関数の g。
 */
struct FVolumetricFogParams {
    FVec3 color          = FVec3{0.62f, 0.70f, 0.82f};
    f32   density        = 0.0f;
    f32   height_falloff = 0.10f;
    f32   height_base    = 0.0f;
    f32   anisotropy     = 0.40f;
    f32   sun_scatter    = 0.18f;
};

/**
 * 物理大気散乱を CPU で評価し equirect 画像へ焼くユーティリティ。
 *
 * @details
 * Hillaire 2020 / Bruneton 風の Rayleigh + Mie 単散乱を per-direction で評価し、
 * 焼いた equirect 画像を FImageBasedLighting に渡すと env cubemap → irradiance →
 * prefilter の IBL chain が物理ベースの sky で構築できる。
 */
class FAtmosphere {
public:
    /**
     * CPU で equirect 画像を焼いて RGBA float 配列を返す。
     *
     * @details
     * 出力は w*h*4 個の float で上から下へ並び、v=0 が +Y 天頂、v=1 が -Y 天底
     * (sIBL Archive 規約と一致)。解析的な太陽ディスクは低解像度の環境テクスチャへ
     * 焼き込まず、最終 skybox pass で描画する。戻り値の TArray は move で呼び出し側に渡される。
     * @param width 焼く equirect 画像の幅 (ピクセル)。
     * @param height 焼く equirect 画像の高さ (ピクセル)。
     * @param params 太陽方向・強度とサンプル数を含む bake パラメータ。
     * @return RGBA float を格納した TArray (w*h*4 要素)。
     */
    static TArray<f32> BakeEquirect(u32 width, u32 height,
                                    const FAtmosphereParams& params) noexcept;
};

/**
 * GPU 物理大気 (WickedEngine / Hillaire 2020 流の GPU compute パイプライン)。
 *
     * @details
     * Transmittance LUT (256x64) を compute で焼き、equirect bake compute がそれを使って
     * Rayleigh+Mie+ozone の単散乱 + 等方多重散乱を per-direction で評価して equirect texture
     * (RGBA32F、解析的な太陽ディスクを含まない) に書く。ReadTexture で CPU へ読み戻し、
     * FImageBasedLighting::LoadEquirectHdrFromMemory
 * に通せば既存の env cubemap → irradiance → prefilter の IBL chain と背景描画がそのまま動く。
 * CPU 版 FAtmosphere::BakeEquirect の置き換え (GPU で高速 + ozone/multiscatter で物理的に正しい空)。
 * 要 Phase 0 compute コア + FDiligentDevice::ReadTexture。Diligent backend 専用。
 */
class FSkyAtmosphere {
public:
    /** compute パイプライン (transmittance / equirect bake) と Transmittance LUT・CB を生成。 */
    TResult<void> Init(IRhiDevice& device,
                       EFormat hdr_format = EFormat::R16G16B16A16_Float) noexcept;

    /** 初期化済みか。 */
    bool Ready() const noexcept { return m_Ready; }

    /**
     * GPU で大気 equirect を焼き CPU の RGBA float 配列へ読み戻す (LoadEquirectHdrFromMemory 互換)。
     *
     * @param device RHI デバイス。
     * @param cl コマンドリスト。
     * @param params 太陽方向・強度。
     * @param width  equirect 幅。
     * @param height equirect 高さ。
     * @param out    出力 (width*height*4 個の f32、move せず resize して埋める)。
     * @return 成功で true (失敗時 out は不定、呼び出し側で CPU fallback)。
     */
    bool BakeEquirect(IRhiDevice& device, IRhiCommandList& cl,
                      const FAtmosphereParams& params,
                      u32 width, u32 height, TArray<f32>& out) noexcept;

    /**
     * Aerial perspective の camera-volume LUT を焼いて返す。
     *
     * @details
     * 48x48x96 froxel の各セルに camera→距離までの大気を積分する。
     * m_ApVol は premultiplied in-scatter、m_ApTransVol は RGB transmittance を保持し、
     * screen uv + 深度→スライスで scene.rgb = scene.rgb*T.rgb + L.rgb として適用する。
     * 3D LUT を物理積分するため滑らか (cubemap サンプルのような «斜めの段» が出ない)。
     * @param inv_view_proj 逆 view-projection (froxel の world ray 復元用)。
     * @param cam_pos カメラ world position (scene 単位)。
     * @param sun_dir 太陽方角 (+Y up)。
     * @param sun_intensity 太陽ピーク輝度。
     * @param max_dist_scene volume がカバーする最大距離 (scene 単位)。
     * @param scene_to_km scene 単位 → 大気 km の換算 (見た目調整。小さいシーンで霞を可視化)。
     * @param cam_alt_km カメラの大気高度 (km、地表 ≈ 0)。
     * @return AP volume (失敗時または scene_to_km<=0 の無効時は nullptr、非所有)。
     */
    IRhiTexture* BuildAerialPerspective(IRhiDevice& device, IRhiCommandList& cl,
                                        const FMat4& inv_view_proj, FVec3 cam_pos,
                                        FVec3 sun_dir, FVec3 sun_intensity,
                                        f32 max_dist_scene, f32 scene_to_km,
                                        f32 cam_alt_km) noexcept;

    /**
     * ローカル volumetric fog を同じ camera-volume に統合するオーバーロード。
     *
     * @param fog ローカル volumetric height fog (density=0 で無効)。
     */
    IRhiTexture* BuildAerialPerspective(IRhiDevice& device, IRhiCommandList& cl,
                                        const FMat4& inv_view_proj, FVec3 cam_pos,
                                        FVec3 sun_dir, FVec3 sun_intensity,
                                        f32 max_dist_scene, f32 scene_to_km,
                                        f32 cam_alt_km,
                                        const FVolumetricFogParams& fog) noexcept;

    /** 直近に焼いた AP volume (BuildAerialPerspective 後に有効、非所有)。 */
    IRhiTexture* ApVolume() const noexcept { return m_ApVol.Get(); }

    /** 直近に焼いた wavelength-dependent AP transmittance volume。 */
    IRhiTexture* ApTransmittanceVolume() const noexcept {
        return m_ApTransVol.Get();
    }

    /**
     * 直近に焼いた local-fog-only volume。
     *
     * @details BuildAerialPerspective に density>0 の fog を渡したフレームだけ有効。
     * Rayleigh/Mie は含まないため、既に物理大気を積分済みの clear sky に安全に使える。
     */
    IRhiTexture* LocalFogVolume() const noexcept {
        return m_LocalFogVolumeValid ? m_LocalFogVol.Get() : nullptr;
    }

    /** Scene-space range represented by LocalFogVolume(). */
    f32 LocalFogMaxDistance() const noexcept {
        return m_LocalFogMaxDistance;
    }

    /** Init 後に physical aerial-perspective volume を再焼成した累積回数。 */
    u64 PhysicalApDispatchCount() const noexcept {
        return m_PhysicalApDispatchCount;
    }

    /** Init 後に local-fog-only volume を再焼成した累積回数。 */
    u64 LocalFogDispatchCount() const noexcept {
        return m_LocalFogDispatchCount;
    }

    /**
     * 深度で camera-volume を終端し、現在の HDR render target へ一度だけ合成する。
     *
     * @details 呼び出し側は depth を DSV に bind せず、描画先だけを load した render pass
     * を開始しておくこと。RGB transmittance の乗算後に premultiplied in-scatter を
     * alpha を壊さない加算 pass で重ね、scene*T+in-scatter を再現する。
     */
    void CompositeAerialPerspective(IRhiCommandList& cl,
                                    IRhiTexture& depth,
                                    IRhiTexture& ap_volume,
                                    IRhiTexture& transmittance_volume,
                                    const FMat4& inv_view_proj,
                                    FVec3 cam_pos,
                                    f32 max_dist_scene,
                                    u32 screen_width,
                                    u32 screen_height) noexcept;

    /**
     * Geometry と cleared-depth 背景へ local-fog-only volume を一度だけ合成する。
     *
     * @details Geometry は再構築した surface 距離で終端する。cloud_depth が有効なら
     * cleared-depth pixel も雲の実距離で終端し、純粋な sky のみ far slice を使う。
     * 物理大気は含まないため、空や雲へ重ねても二重散乱にならない。
     */
    void CompositeLocalFog(IRhiCommandList& cl,
                           IRhiTexture& depth,
                           IRhiTexture& local_fog_volume,
                           IRhiTexture* cloud_depth,
                           const FMat4& inv_view_proj,
                           FVec3 cam_pos,
                           f32 max_dist_scene,
                           u32 screen_width,
                           u32 screen_height) noexcept;

    /** 全 GPU リソースを解放 (acs_editor_destroy から呼ぶ。UAF 防止)。 */
    void Shutdown() noexcept;

private:
    struct FVolumeCacheKey {
        FMat4 invViewProj{};
        FVec4 camPos{};
        FVec4 sunDir{};
        FVec4 sunInt{};
        FVec4 apParams{};
        FVec4 fogColorDensity{};
        FVec4 fogParams{};
    };
    static_assert(sizeof(FVolumeCacheKey) == 160u,
                  "volume cache keys must not contain implicit padding");

    static bool SameVolumeCacheKey(const FVolumeCacheKey& lhs,
                                   const FVolumeCacheKey& rhs) noexcept;

    bool                     m_Ready = false;
    bool                     m_LutsReady = false;      // transmittance + multi-scattering は一度だけ焼く
    TUniquePtr<IRhiShader>   m_TransCs;
    TUniquePtr<IRhiShader>   m_BakeCs;
    TUniquePtr<IRhiPipeline> m_TransPipe;
    TUniquePtr<IRhiPipeline> m_BakePipe;
    TUniquePtr<IRhiTexture>  m_TransLut;    // 256x64 RGBA16F UAV/SRV
    TUniquePtr<IRhiShader>   m_MultiCs;     // 多重散乱 LUT CS (WE multiScatteredLuminanceLut)
    TUniquePtr<IRhiPipeline> m_MultiPipe;
    TUniquePtr<IRhiTexture>  m_MultiLut;    // 32x32 RGBA16F UAV/SRV (Fms)
    TUniquePtr<IRhiTexture>  m_Equirect;    // width x height RGBA32F UAV (readback source)
    TUniquePtr<IRhiBuffer>   m_Cb;          // sun dir + intensity + ground albedo
    TUniquePtr<IRhiShader>   m_ApCs;        // aerial perspective froxel CS
    TUniquePtr<IRhiPipeline> m_ApPipe;
    TUniquePtr<IRhiShader>   m_LocalFogCs;  // scalar local-fog-only froxel CS
    TUniquePtr<IRhiPipeline> m_LocalFogPipe;
    TUniquePtr<IRhiTexture>  m_ApVol;       // 48x48x96 RGBA16F premultiplied in-scatter
    TUniquePtr<IRhiTexture>  m_ApTransVol;  // 48x48x96 RGBA16F RGB transmittance
    TUniquePtr<IRhiBuffer>   m_ApCb;        // AP cbuffer (invVP/cam/sun/params)
    TUniquePtr<IRhiTexture>  m_LocalFogVol; // 同解像度の local-fog-only volume
    TUniquePtr<IRhiBuffer>   m_LocalFogCb;  // AP dispatch と同フレームに安全に使う専用 CB
    bool                     m_LocalFogVolumeValid = false;
    f32                      m_LocalFogMaxDistance = kLocalVolumetricFogMaxDistance;
    FVolumeCacheKey          m_PhysicalApCacheKey{};
    FVolumeCacheKey          m_LocalFogCacheKey{};
    bool                     m_PhysicalApCacheValid = false;
    bool                     m_LocalFogCacheValid = false;
    u64                      m_PhysicalApDispatchCount = 0;
    u64                      m_LocalFogDispatchCount = 0;
    TUniquePtr<IRhiShader>   m_ApCompositeVs;
    TUniquePtr<IRhiShader>   m_ApCompositePs;
    TUniquePtr<IRhiPipeline> m_ApCompositePipe;
    TUniquePtr<IRhiShader>   m_ApMultiplyPs;
    TUniquePtr<IRhiPipeline> m_ApMultiplyPipe;
    TUniquePtr<IRhiShader>   m_ApAddPs;
    TUniquePtr<IRhiPipeline> m_ApAddPipe;
    TUniquePtr<IRhiBuffer>   m_ApCompositeCb;       // physical AP draws only
    TUniquePtr<IRhiBuffer>   m_LocalFogCompositeCb; // later local-fog draw only
    u32                      m_EqW = 0, m_EqH = 0;
};

} // namespace acs

// ===================== render/Blit.h =====================
// SPDX-License-Identifier: Apache-2.0
// フルスクリーン texture コピー (ブリット) ユーティリティ
//
// 用途: 1 つの Texture2D (通常は描画済みの RT) をもう 1 つの Texture2D
//       (is_render_target=true で作成済) へ pixel-perfect にコピーする。
//       直接 GPU copy が RHI に無いため、フルスクリーン三角形 + テクスチャ
//       sample で代替する標準テクニック。
//
// 想定ユースケース: スクリーンスペース屈折のための background capture
// (HDR scene color → 屈折オブジェクトが sample する複製テクスチャ)。
//
// 使い方:
//   FBlit blit;
//   blit.Init(*device, hdr_format);                    // 1 度だけ
//   // フレーム中、コピーしたい時点で:
//   blit.Copy(*cl, *src_hdr, *dst_bg);                 // dst の format == hdr_format


namespace acs {

/**
 * フルスクリーン三角形で 1 つのテクスチャを別のテクスチャへコピーするブリット。
 *
 * @details
 * 直接 GPU copy が RHI に無いため、フルスクリーン三角形 + テクスチャ sample で
 * pixel-perfect コピーを行う標準テクニック。出力 RT のフォーマットは Init 時に
 * PSO へ焼き込むため、別フォーマットへコピーしたい場合は別インスタンスを使う。
 */
class FBlit {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FBlit() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FBlit() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FBlit(const FBlit&)            = delete;

    /** コピー代入も禁止。 */
    FBlit& operator=(const FBlit&) = delete;

    /**
     * シェーダとパイプラインを生成して初期化する。
     *
     * @details
     * rt_format は Copy の出力 RT のフォーマットで、PSO に焼き込まれる。出力 RT を
     * 別フォーマットに切り替えたい場合は別の FBlit インスタンスを使うこと。
     * @param device シェーダ・パイプライン生成に使う RHI デバイス。
     * @param rt_format 出力 RT のフォーマット (PSO に焼き込む)。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, EFormat rt_format) noexcept;

    /** 確保した GPU リソースを解放する (多重呼び出し安全)。 */
    void Shutdown() noexcept;

    /**
     * src を dst へフルスクリーン pass でコピーする。
     *
     * @details
     * dst は is_render_target=true で Init 時の rt_format と一致すること。内部で
     * BeginRenderToTextureLoad(dst) → SetPipeline → SetTexture → Draw(3) →
     * EndRenderToTexture(dst) を行う。全 pixel を上書きするので clear 不要、
     * viewport は dst のサイズに自動設定される。
     * @param cmd コマンドを積むコマンドリスト。
     * @param src コピー元テクスチャ。
     * @param dst コピー先 RT (rt_format に一致すること)。
     */
    void Copy(IRhiCommandList& cmd, IRhiTexture& src, IRhiTexture& dst) noexcept;

    /**
     * 内部のブリット用パイプラインを返す。
     *
     * @return ブリット用パイプライン (未初期化なら nullptr)。
     */
    IRhiPipeline* Pipeline() const noexcept { return m_Pipeline.Get(); }

private:
    /** フルスクリーン三角形の頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** source texture を素 sample するピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** ブリット描画のパイプライン。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;
};

} // namespace acs

// ===================== render/BurnEffect.h =====================
// SPDX-License-Identifier: Apache-2.0
// 紙が燃えて消える per-pixel ディゾルブ (2D オーバーレイ用シェーダ効果)
//
// 用途: 2D の矩形領域に「燃える紙」を 1 枚かぶせ、progress 0→1 で燃え際 (白熱→橙→
//       黒コゲ) が進みながら下の描画内容を出現させる。ピクセル単位の手続きノイズで
//       描くのでセル/ドットにならず高解像度。FSky と同じく自前の VS/PS/PSO/CB を持ち、
//       コマンドリストに 6 頂点のクアッドを 1 回 Draw するだけ (VB 不要)。


namespace acs {

/** 燃えディゾルブのパラメータ。 */
struct FBurnParams {
    /** 0=全部紙, 1=全部燃えて下が見える。 */
    f32   progress = 0.0f;

    /** 燃え際の帯幅 (0.05〜0.2)。 */
    f32   edge     = 0.12f;

    /** 燃え際の基準色 (橙)。 */
    FVec3 ember    = FVec3{1.0f, 0.45f, 0.06f};

    /** 紙 (覆い) の色。 */
    FVec3 paper    = FVec3{0.88f, 0.84f, 0.74f};

    /** ノイズ周波数 (大きいほど細かい炎縁)。 */
    f32   freq     = 7.0f;

    /** アニメ用の時間 (炎のゆらぎ。0 で静止)。 */
    f32   time     = 0.0f;

    /** ドット調の分割数 (0=なめらか最高解像度、N=N分割の四角ドット)。 */
    f32   cells    = 0.0f;
};

/**
 * 紙が燃えるディゾルブをピクセル単位で描く 2D オーバーレイ効果。
 *
 * @details DX12 raw / Diligent どちらでも動く (FSky と同じ生パイプライン)。アルファ
 *          ブレンドで重ね、燃え尽きた画素は discard して下の内容を見せる。
 */
class FBurnEffect {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FBurnEffect() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FBurnEffect() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FBurnEffect(const FBurnEffect&) = delete;

    /** コピー代入も禁止。 */
    FBurnEffect& operator=(const FBurnEffect&) = delete;

    /**
     * VS/PS/PSO/定数バッファを生成する。
     *
     * @param device リソース生成に使う RHI デバイス。
     * @param rt_format 描画先カラーターゲットのフォーマット (バッチと一致させる)。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, EFormat rt_format) noexcept;

    /** 確保した GPU リソースを解放する。 */
    void Shutdown() noexcept;

    /** Init 済みで描画可能か。 */
    bool Ready() const noexcept { return m_Pipeline.Get() != nullptr && m_Cb[0].Get() != nullptr; }

    /**
     * 矩形領域に燃えディゾルブを 1 枚描く。
     *
     * @param cl コマンドを積むコマンドリスト。
     * @param x,y 矩形左上 (スクリーン px)。
     * @param w,h 矩形サイズ (px)。
     * @param screen_w,screen_h 出力解像度 (NDC 変換用)。
     * @param p 燃えパラメータ。
     */
    void Draw(IRhiCommandList& cl, f32 x, f32 y, f32 w, f32 h,
              f32 screen_w, f32 screen_h, const FBurnParams& p) noexcept;

private:
    /** クアッドを出す頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** 燃えを計算するピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** 描画パイプライン (アルファブレンド)。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;

    /** 1 フレーム内で複数回 Draw しても CB が衝突しないようリングで持つ。 */
    static constexpr u32     kRing = 32;

    /** パラメータ定数バッファのリング。 */
    TUniquePtr<IRhiBuffer>   m_Cb[kRing];

    /** 次に使う CB スロット (Draw ごとに進める)。 */
    u32                      m_CbIdx = 0;
};

} // namespace acs

// ===================== render/DebugDraw.h =====================
// SPDX-License-Identifier: Apache-2.0
// FDebugDraw3D — 3D ライン (LineList) のデバッグ描画。コライダーの wireframe、
// AABB、レイ等を色付きで重ねるのに使う。
//
//   FDebugDraw3D dd;
//   dd.Init(*dev, renderer.ColorFormat());
//   ...
//   dd.Begin();
//   dd.Wireframe(positions, vcount, indices, icount, {0.4f,1,0.4f,1});  // メッシュ
//   dd.Aabb(box, {1,1,0,1});
//   dd.Line(a, b, {0,1,1,1});                                           // レイ等
//   dd.End(*cl, view_proj);   // backbuffer / RT が bind 済みの状態で
//
// depth 無し (常に手前に重なる overlay)。ACS 規約準拠 (noexcept / TResult / 非コピー)。


namespace acs {

/**
 * 3D ライン (LineList) のデバッグ描画。
 *
 * @details
 * コライダーの wireframe、AABB、レイ等を色付きで overlay するのに使う。Begin で
 * 頂点バッファをクリアし、Line/Aabb/Wireframe でライン頂点を積み、End で現在 bind
 * 中のターゲットへ描画する。depth テスト無しで常に手前に重なる。ACS 規約準拠
 * (noexcept / TResult / 非コピー)。
 */
class FDebugDraw3D {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FDebugDraw3D() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FDebugDraw3D() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FDebugDraw3D(const FDebugDraw3D&)            = delete;

    /** コピー代入も禁止。 */
    FDebugDraw3D& operator=(const FDebugDraw3D&) = delete;

    /**
     * GPU リソース (シェーダ・パイプライン・頂点/定数バッファ) を確保する。
     *
     * @param device リソース生成に使う RHI デバイス。
     * @param rt_format 描画先レンダーターゲットの色フォーマット。
     * @param max_lines 1 フレームで積めるライン本数の上限 (頂点バッファ容量)。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, EFormat rt_format, u32 max_lines = 16384) noexcept;

    /** 確保した GPU リソースを解放する。 */
    void Shutdown() noexcept;

    /** フレームのライン蓄積を開始する (頂点バッファをクリアする)。 */
    void Begin() noexcept;

    /**
     * 2 点を結ぶ 1 本の線を積む。
     *
     * @param a 始点。
     * @param b 終点。
     * @param color 線の色 (RGBA)。
     */
    void Line(FVec3 a, FVec3 b, FVec4 color) noexcept;

    /**
     * AABB の 12 本のエッジを線で積む。
     *
     * @param box 描画する軸並行境界ボックス。
     * @param color 線の色 (RGBA)。
     */
    void Aabb(const FAabb3& box, FVec4 color) noexcept;

    /**
     * 三角形インデックス列の全エッジを線で積む (メッシュ/凸包の wireframe)。
     *
     * @param positions 頂点座標配列。
     * @param vertex_count positions の頂点数。
     * @param indices 三角形を構成するインデックス列。
     * @param index_count indices の要素数 (3 の倍数)。
     * @param color 線の色 (RGBA)。
     */
    void Wireframe(const FVec3* positions, u32 vertex_count,
                   const u32* indices, u32 index_count, FVec4 color) noexcept;

    /**
     * 積んだ全ラインを現在 bind 中のターゲットへ描画する。
     *
     * @param cl コマンドを積むコマンドリスト。
     * @param view_proj 適用する view-projection 行列 (model を畳んだ MVP でもよい)。
     */
    void End(IRhiCommandList& cl, const FMat4& view_proj) noexcept;

    /**
     * 現在積まれているライン本数を返す。
     *
     * @return ライン本数 (頂点数 / 2)。
     */
    u32 LineCount() const noexcept { return static_cast<u32>(m_Verts.Size() / 2); }

private:
    /** 1 本のラインを構成する 1 頂点 (位置 + RGBA カラー)。 */
    struct FLineVtx { f32 px, py, pz, r, g, b, a; };

    /** ライン描画の頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** ライン描画のピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** ライン描画のパイプライン (LineList、depth 無し)。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;

    /** ライン頂点を保持する GPU 頂点バッファ。 */
    TUniquePtr<IRhiBuffer>   m_Vb;

    /** view-projection 行列を渡す定数バッファ。 */
    TUniquePtr<IRhiBuffer>   m_Cb;

    /** CPU 側のライン頂点蓄積 (End で頂点バッファへ転送)。 */
    TArray<FLineVtx>          m_Verts;

    /** 頂点バッファに収まる頂点数の上限 (max_lines * 2)。 */
    u32                      m_MaxVerts = 0;
};

} // namespace acs

// ===================== render/Fxaa.h =====================
// SPDX-License-Identifier: Apache-2.0
// FXAA (Fast Approximate Anti-Aliasing) フルスクリーンパス
//
// 用途: ジオメトリ AA (MSAA) を持たないパスの後段で、輝度ベースのエッジ平滑化を
//       1 パスで掛ける。2D スプライト/ポリゴン描画 (エディタビューポート等) の
//       ジャギー低減が主目的。
//
// 使い方:
//   FFxaa fxaa;
//   fxaa.Init(*device, backbuffer_format);             // 1 度だけ
//   // フレーム中: シーンをオフスクリーン RT に描いた後、出力先 (backbuffer 等) を
//   // bind した状態で:
//   fxaa.Apply(*cl, *scene_rt);                        // FXAA 解決しつつ全画面描画


namespace acs {

/**
 * FXAA をフルスクリーン三角形 1 パスで掛けるポストエフェクト。
 *
 * @details
 * FXAA 3.11 の簡易品質版。中心+対角 4 近傍の輝度からエッジ方向を推定し、
 * エッジに沿って 2/4 タップのブレンドを行う。低コントラスト画素は早期 return で
 * 素通しするため、ベタ塗り領域やテキストのにじみは最小限。入力サイズは
 * GetDimensions で取得するので cbuffer 不要。
 */
class FFxaa {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FFxaa() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FFxaa() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FFxaa(const FFxaa&)            = delete;

    /** コピー代入も禁止。 */
    FFxaa& operator=(const FFxaa&) = delete;

    /**
     * シェーダとパイプラインを生成して初期化する。
     *
     * @param device シェーダ・パイプライン生成に使う RHI デバイス。
     * @param rt_format 出力先 RT のフォーマット (PSO に焼き込む)。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, EFormat rt_format) noexcept;

    /** 確保した GPU リソースを解放する (多重呼び出し安全)。 */
    void Shutdown() noexcept;

    /**
     * 現在 bind 中のターゲットへ src を FXAA 解決しつつ全画面描画する。
     *
     * @details
     * FBlit::Copy と違い出力 RT の bind は行わない。呼ぶ前に BeginRenderToSwapchain
     * 等で出力先を bind し、viewport を設定しておくこと (全 pixel を上書きする)。
     * @param cmd コマンドを積むコマンドリスト。
     * @param src FXAA を掛けるシーンテクスチャ (SRV 状態であること)。
     */
    void Apply(IRhiCommandList& cmd, IRhiTexture& src) noexcept;

private:
    /** フルスクリーン三角形の頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** FXAA ピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** FXAA 描画のパイプライン。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;
};

} // namespace acs

// ===================== render/HiZ.h =====================
// SPDX-License-Identifier: Apache-2.0
// Hi-Z (Hierarchical-Z) min-depth pyramid
//
// level 0 は scene_depth の 8x8 ブロックごとの最近接 NDC depth、level N は
// level N-1 の厳密な 2x2 min 縮約で、最終 level は 1x1 になる。SSR 等の
// screen-space ray march が空の大領域を粗い level からスキップするために使う。
//
// 設計上の選択:
//   ・同じ mip chain を持つ physical texture を 2 本確保し、even level と odd
//     level を交互に書く。同一 resource 内の mip を SRV/RTV 同時利用しないため、
//     whole-resource transition の Raw DX12 / Diligent 双方で安全。
//   ・physical base size は logical 1/8 size を各軸 NextPowerOfTwo に padding。
//     padding depth=1.0 とすることで、全 level の cell が 8<<level pixel の
//     一様な領域に対応し、odd resolution の可変幅 cell を作らない。
//   ・EFormat は R32G32_Float。.r に min depth、.g は未使用。多段縮約で half の
//     round-up が累積して min depth を過大評価することを避け、skip を保守的に保つ。
//   ・sky pixel (depth >= 0.9999) は無視 — 屋外シーンで「ground - sky」の
//     skip が大きく走るのは安全 (空には反射先が無い)
//
// 使い方 (SSR 統合):
//   FHiZ hiz;
//   hiz.Init(*dev, w, h);
//   // 毎フレーム main pass の depth が完成したあと、SSR 前に:
//   hiz.Build(*dev, *cl, scene_depth);
//   ssr.Render(..., hiz.Texture());     // 旧 1/8 coarse path (level 0)
//   // hierarchical path は EvenTexture/OddTexture を両方 bind し、
//   // even level を EvenTexture、odd level を OddTexture の同じ mip から読む。
//
// 上位の SSR shader 側で skip-ahead する具体実装 (FSsr.cpp) と一体で機能する。
// Hi-Z を渡さない場合も FSsr で OK (nullptr fallback)。


namespace acs {

/**
 * scene_depth から 1/8 解像度を level 0 とする min-depth pyramid を焼く Hi-Z。
 *
 * @details
 * level 0 の各 texel は元 depth の 8x8 ブロック中の最近接値を持ち、後続 level は
 * 直前 level の厳密な 2x2 min 縮約になる。2 本の R32G32_Float texture に level を
 * 偶奇で分けることで、同一 resource の SRV/RTV 同時利用を避ける。
 */
class FHiZ {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FHiZ() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FHiZ() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FHiZ(const FHiZ&) = delete;

    /** コピー代入も禁止。 */
    FHiZ& operator=(const FHiZ&) = delete;

    /**
     * GPU リソースを確保する。
     *
     * @details Hi-Z は内部で ceil(src_w / 8) x ceil(src_h / 8) サイズで確保される。
     * @param device RT・パイプライン生成に使う RHI デバイス。
     * @param src_width 入力 scene_depth の幅。
     * @param src_height 入力 scene_depth の高さ。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, u32 src_width, u32 src_height) noexcept;

    /** 確保した GPU リソースを解放する (多重呼び出し安全)。 */
    void Shutdown() noexcept;

    /**
     * 解像度変更時に内部 RT を作り直す (ウィンドウリサイズで呼ぶ)。
     *
     * @param src_width 新しい入力 scene_depth の幅。
     * @param src_height 新しい入力 scene_depth の高さ。
     * @return 成功なら空の TResult、再確保失敗ならエラー。
     */
    TResult<void> Resize(u32 src_width, u32 src_height) noexcept;

    /**
     * scene_depth から min-depth pyramid 全 level を焼く。
     *
     * @param device 描画に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @param scene_depth 入力 depth (shader_visible_depth=true の D32_Float)。
     */
    void Build(IRhiDevice& device, IRhiCommandList& cl,
               IRhiTexture& scene_depth) noexcept;

    /**
     * level 0 を保持する physical texture を返す。
     *
     * @details 旧 coarse-only SSR との互換 API。返値は EvenTexture() と同じで、
     * level 0 は mip 0 に格納される。それ以外の even mip も有効だが odd mip は未定義。
     * @return even-level texture (R32G32_Float、.r=min depth)。
     */
    IRhiTexture* Texture() const noexcept { return m_HizEven.Get(); }

    /**
     * 偶数 level を保持する physical texture を返す。
     *
     * @return level 0,2,4,... が同番号 mip に格納された texture。
     */
    IRhiTexture* EvenTexture() const noexcept { return m_HizEven.Get(); }

    /**
     * 奇数 level を保持する physical texture を返す。
     *
     * @return level 1,3,5,... が同番号 mip に格納された texture。
     */
    IRhiTexture* OddTexture() const noexcept { return m_HizOdd.Get(); }

    /**
     * pyramid の有効 level 数を返す。
     *
     * @return level 0 を含み、最終 1x1 level までの段数。
     */
    u32 MipCount() const noexcept { return m_MipCount; }

    /**
     * 入力 scene_depth の幅を返す。
     *
     * @return Init/Resize で渡された src 幅。
     */
    u32 SrcWidth() const noexcept { return m_SrcW; }

    /**
     * 入力 scene_depth の高さを返す。
     *
     * @return Init/Resize で渡された src 高さ。
     */
    u32 SrcHeight() const noexcept { return m_SrcH; }

    /**
     * Hi-Z RT の幅を返す。
     *
     * @return Hi-Z RT の幅 (src/8)。
     */
    u32 Width() const noexcept { return m_HizW; }

    /**
     * Hi-Z RT の高さを返す。
     *
     * @return Hi-Z RT の高さ (src/8)。
     */
    u32 Height() const noexcept { return m_HizH; }

    /**
     * padded physical texture の幅を返す。
     *
     * @return NextPowerOfTwo(Width())。SSR の mip texel address 計算に使う。
     */
    u32 PhysicalWidth() const noexcept { return m_PhysicalW; }

    /**
     * padded physical texture の高さを返す。
     *
     * @return NextPowerOfTwo(Height())。SSR の mip texel address 計算に使う。
     */
    u32 PhysicalHeight() const noexcept { return m_PhysicalH; }

    /** 1 Hi-Z texel が覆う元 depth のブロック辺長。 */
    static constexpr u32 kBlockSize = 8;

    /**
     * RHI texture に確保する最大 level 数。
     *
     * @details level 0 が 1/8 解像度なので、D3D12 の最大 16384px texture でも
     * 必要なのは 12 level。16 は十分な余裕を持つ。
     */
    static constexpr u32 kMaxMipLevels = 16;

private:
    /**
     * 偶奇 2 本の min-depth mip texture を生成する。
     *
     * @param device RT 生成に使う RHI デバイス。
     * @param src_w 入力 scene_depth の幅。
     * @param src_h 入力 scene_depth の高さ。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreateRT(IRhiDevice& device, u32 src_w, u32 src_h) noexcept;

    /**
     * level 0 抽出と pyramid 縮約用の VS/PS/PSO を生成する。
     *
     * @param device パイプライン生成に使う RHI デバイス。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreatePipeline(IRhiDevice& device) noexcept;

    /** Init で受け取った device (Resize で再利用)。 */
    IRhiDevice* m_Device = nullptr;

    /** 入力 scene_depth の幅。 */
    u32 m_SrcW = 0;

    /** 入力 scene_depth の高さ。 */
    u32 m_SrcH = 0;

    /** Hi-Z RT の幅 (src/8)。 */
    u32 m_HizW = 0;

    /** Hi-Z RT の高さ (src/8)。 */
    u32 m_HizH = 0;

    /** power-of-two padding 後の physical texture 幅。 */
    u32 m_PhysicalW = 0;

    /** power-of-two padding 後の physical texture 高さ。 */
    u32 m_PhysicalH = 0;

    /** level 0 から最終 1x1 までの有効 level 数。 */
    u32 m_MipCount = 0;

    /** 偶数 level を同番号 mip に保持する physical texture。 */
    TUniquePtr<IRhiTexture> m_HizEven;

    /** 奇数 level を同番号 mip に保持する physical texture。 */
    TUniquePtr<IRhiTexture> m_HizOdd;

    /** フルスクリーン三角形の頂点シェーダ。 */
    TUniquePtr<IRhiShader> m_Vs;

    /** 8x8 ブロックから level 0 を抽出するピクセルシェーダ。 */
    TUniquePtr<IRhiShader> m_PsBase;

    /** 直前 level から次 level を min 縮約するピクセルシェーダ。 */
    TUniquePtr<IRhiShader> m_PsReduce;

    /** scene depth から level 0 を作るパイプライン。 */
    TUniquePtr<IRhiPipeline> m_BasePipeline;

    /** pyramid の level N-1 から N を作るパイプライン。 */
    TUniquePtr<IRhiPipeline> m_ReducePipeline;

    /**
     * level ごとの immutable 定数バッファ。
     *
     * @details index N は src mip=N-1 / dst mip=N を保持する。各 draw が別 resource
     * を使うため、Raw DX12 で同一 upload CB を同フレーム中に上書きしない。
     */
    TUniquePtr<IRhiBuffer> m_LevelCb[kMaxMipLevels];
};

} // namespace acs

// ===================== render/Ibl.h =====================
// SPDX-License-Identifier: Apache-2.0
// Image-Based Lighting
//
// PBR の ambient 項を「環境マップから事前積分した光」で置き換える。
// 構成要素:
//   ・BRDF LUT       — 2D 256x256 RG16F。GGX split-sum approximation の scale+bias
//   ・環境 cubemap   — シーンの背景 (FSky 等から captured)。1024x1024x6、R11G11B10_Float
//   ・拡散 irradiance cubemap — 64x64x6、半球積分された diffuse 反射
//   ・specular prefilter cubemap — 512x512x6 (7 mip)、roughness 段階別 GGX 反射
//
// 使い方 (HelloIbl):
//   FImageBasedLighting ibl;
//   ibl.EnsureBrdfLut(*dev, *cl);              // 初回のみ LUT 生成 (256x256)
//   ibl.EnsureEnvCubemap(*dev, *cl, sky);       // 初回のみ env cubemap キャプチャ
//   // (irradiance / prefilter を生成してから:)
//   // ibl.EnsureIrradiance(*cl);                // 環境 → irradiance
//   // ibl.EnsurePrefilter(*cl);                 // 環境 → prefilter (mip)
//   // pbr.SetIbl(*ibl.IrradianceMap(), *ibl.PrefilterMap(), *ibl.BrdfLut());
//
// 注意: IBL は Diligent backend 専用の本実装 (BeginRenderToTextureSlice / cubemap 依存)。
//       raw-DX12 backend では各 Build/Ensure が ACS_ERR(Render, 88) を返す
//       (fake-success しない)。高度3D を使うには -DACS_RENDER_DILIGENT=ON でビルドする。
//       (raw-DX12 = 軽量 2D/基本3D backend、Diligent = 公式の高度3D backend)


namespace acs {

class FSky;

/**
 * Image-Based Lighting。PBR の ambient 項を環境マップから事前積分した光で置き換える。
 *
 * @details
 * 構成要素は BRDF LUT (256x256 RG16F、GGX split-sum の scale+bias)、環境 cubemap
 * (1024x1024x6 R11G11B10_Float)、拡散 irradiance cubemap (64x64x6)、specular prefilter
 * cubemap (512x512x6, 7 mip)。Diligent backend 専用の本実装で、raw-DX12 backend では
 * 各 Build/Ensure が ACS_ERR(Render, 88) を返す (fake-success しない)。
 */
class FImageBasedLighting {
public:
    /** 空状態で構築する (各 GPU リソースは Ensure 系で遅延生成)。 */
    FImageBasedLighting() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FImageBasedLighting() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FImageBasedLighting(const FImageBasedLighting&)            = delete;

    /** コピー代入も禁止。 */
    FImageBasedLighting& operator=(const FImageBasedLighting&) = delete;

    /**
     * 初回呼び出しで BRDF LUT を 1 回だけ生成する (以降は no-op)。
     *
     * @details cl は frame 内 (BeginFrame と EndFrame の間) で記録中である必要がある。
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> EnsureBrdfLut(IRhiDevice& device, IRhiCommandList& cl) noexcept;

    /**
     * 初回呼び出しで env cubemap を FSky 手続き式からキャプチャする。
     *
     * @details
     * 1024x1024x6 / R11G11B10_Float を各 face 6 回の per-slice draw で塗る。sky の現在の
     * パラメータ (sun_dir / colors 等) がスナップショットされる。再キャプチャするには
     * Shutdown() で全 reset するか ResetEnvCubemap() を使う。
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @param sky キャプチャ元の手続き式空。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> EnsureEnvCubemap(IRhiDevice& device, IRhiCommandList& cl,
                                  const FSky& sky) noexcept;

    /**
     * 既存 env cubemap を破棄し equirectangular HDR 画像から新しい env cubemap を作る。
     *
     * @details
     * 内部で R32G32B32A32_Float の Texture2D に upload し、6 face をピクセルシェーダで
     * 塗り直す。irradiance / prefilter は呼び出し側で再 Ensure する必要がある。
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @param rgba_float width × height × 4 個の float (row-major / top-down、v=0 が天頂 +Y、v=1 が天底 -Y)。
     * @param width 画像の幅 (px)。
     * @param height 画像の高さ (px)。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> LoadEquirectHdrFromMemory(IRhiDevice& device, IRhiCommandList& cl,
                                            const f32* rgba_float, u32 width, u32 height) noexcept;

    /**
     * Excludes an analytic direct-light disc from diffuse/specular IBL
     * convolution while keeping that disc visible in the environment skybox.
     *
     * Finite convolution sequences sample a sub-pixel HDR sun disc as
     * structured fireflies, and FPbrShader already evaluates the same sun via
     * its directional-light BRDF.  Set cosine_half_angle > 1 to disable.
     * Call this before EnsureIrradiance/EnsurePrefilter during an environment
     * rebuild.  It does not destroy already-built GPU products; changing it
     * after a build requires the existing safe sequence: wait for GPU idle,
     * ResetEnvCubemap(), then rebuild.
     */
    void SetDirectLightExclusion(FVec3 direction,
                                 f32 cosine_half_angle) noexcept;

    /**
     * equirect 画像から SH 9 light probe を CPU 側で計算する。
     *
     * @details
     * Ramamoorthi-Hanrahan の L_l,m 球面調和係数 9 個を求めて out_sh_rgb に書き出す。
     * 各 out_sh_rgb[i].xyz が RGB 係数で .w は不使用 (CB layout の便宜上 FVec4)。後段
     * FPbrShader で SH 9 ambient mode に切替でき、irradiance cubemap の圧縮版 (144B のみ)
     * として diffuse irradiance を近似する。規約: v=0 が +Y、v=1 が -Y、u=0 が phi=-π。
     * @param rgba_float equirect 画像の RGBA float ピクセル列。
     * @param width 画像の幅 (px)。
     * @param height 画像の高さ (px)。
     * @param out_sh_rgb 計算した SH 係数 9 個の書き出し先。
     */
    static void ComputeSh9FromEquirect(const f32* rgba_float,
                                        u32 width, u32 height,
                                        FVec4 out_sh_rgb[9]) noexcept;

    /**
     * 初回呼び出しで diffuse irradiance cubemap を env cubemap の半球積分から作る。
     *
     * @details
     * 64x64x6 / R11G11B10_Float。EnsureEnvCubemap が完了していないと失敗する。出力は
     * (1/π) ∫_Ω L_env(ω) (N·ω) dω で、Lambert diffuse の ambient 項として
     * diffuse = albedo * irradiance_cube.Sample(N) で使う。
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> EnsureIrradiance(IRhiDevice& device, IRhiCommandList& cl) noexcept;

    /**
     * 初回呼び出しで specular prefilter cubemap を env cubemap の GGX 積分から作る。
     *
     * @details
     * 512x512x6 / R11G11B10_Float / 7 mips。各 mip が roughness 段階に対応する
     * (mip 0 = roughness 0 / 鏡面、mip 6 = roughness 1)。実行時 PBR specular は
     * F = F0 * lut.r + lut.g、specular = prefilter.SampleLevel(R, roughness*(mips-1)).rgb * F。
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> EnsurePrefilter(IRhiDevice& device, IRhiCommandList& cl) noexcept;

    /**
     * デバッグ用に任意の cubemap を fullscreen quad の skybox として現在の RT へ描く。
     *
     * @details
     * rt_format / depth_format は現在 bind 中の swapchain と一致させること。depth_test /
     * write は無効 (背景描画)。初回呼び出しで PSO/CB を lazy init し、env_cube / irradiance
     * / prefilter で同じ pipeline を共有する。
     * @param device リソース生成・描画に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @param cube 描画する cubemap テクスチャ。
     * @param view_proj 適用する view-projection 行列。
     * @param eye カメラ位置 (視線方向の算出に使う)。
     * @param rt_format 現在 bind 中の RT の色フォーマット。
     * @param depth_format 現在 bind 中の depth フォーマット。
     * @param mip_level サンプルする mip 段階 (prefilter で roughness 段階を選ぶとき 0..prefilter_mips-1、env/irradiance では 0)。
     */
    void DrawSkybox(IRhiDevice& device, IRhiCommandList& cl,
                    IRhiTexture& cube,
                    const FMat4& view_proj, FVec3 eye,
                    EFormat rt_format, EFormat depth_format,
                    f32 mip_level = 0.0f,
                    FVec3 sun_direction = FVec3{0.0f, 1.0f, 0.0f},
                    FVec3 sun_radiance = FVec3{},
                    f32 sun_angular_radius = 0.0f) noexcept;

    /**
     * env_cube を skybox として現在の RT へ描く利便ラッパ。
     *
     * @param device リソース生成・描画に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @param view_proj 適用する view-projection 行列。
     * @param eye カメラ位置。
     * @param rt_format 現在 bind 中の RT の色フォーマット。
     * @param depth_format 現在 bind 中の depth フォーマット。
     * @param sun_direction 解析的に描く太陽への方向。正規化は内部で行う。
     * @param sun_radiance 太陽ディスクの線形 HDR 放射輝度。0 ならディスクを描かない。
     * @param sun_angular_radius 太陽の角半径 (rad)。0 ならディスクを描かない。
     *
     * @details
     * 太陽ディスクは env cubemap へ焼き込まず、最終ビューポート解像度で解析的に
     * 描画する。これにより低解像度 equirect のテクセル形状が四角く拡大されず、
     * 後段の volumetric cloud composite が自然にディスクを遮蔽できる。
     */
    void DrawEnvSkybox(IRhiDevice& device, IRhiCommandList& cl,
                       const FMat4& view_proj, FVec3 eye,
                       EFormat rt_format, EFormat depth_format,
                       FVec3 sun_direction = FVec3{0.0f, 1.0f, 0.0f},
                       FVec3 sun_radiance = FVec3{},
                       f32 sun_angular_radius = 0.0f) noexcept;

    /**
     * 環境 cubemap (とそれに依存する irradiance / prefilter) だけを reset する。
     *
     * @details
     * FSky preset 切替などで env を作り直したいときに使い、BRDF LUT (sky 非依存) は残せる。
     * 呼び出し前にデバイスの WaitIdle() を呼ぶこと: 前フレームの GPU 描画がまだこのテクスチャ
     * を参照中だと UB になる。
     */
    void ResetEnvCubemap() noexcept;

    /** 確保した全 GPU リソース (LUT・各 cubemap・skybox パイプライン) を解放する。 */
    void Shutdown() noexcept;

    /**
     * BRDF LUT を返す。
     *
     * @return BRDF LUT (256x256 RG16F)。EnsureBrdfLut 完了前は nullptr。
     */
    IRhiTexture* BrdfLut()    const noexcept { return m_BrdfLut.Get(); }

    /**
     * BRDF LUT が生成済みかを返す。
     *
     * @return 生成済みなら true。
     */
    bool         HasBrdfLut() const noexcept { return static_cast<bool>(m_BrdfLut); }

    /**
     * 環境 cubemap を返す。
     *
     * @return 環境 cubemap (1024x1024x6 R11G11B10_Float)。EnsureEnvCubemap 完了前は nullptr。
     */
    IRhiTexture* EnvCubemap()    const noexcept { return m_EnvCube.Get(); }

    /**
     * 環境 cubemap が生成済みかを返す。
     *
     * @return 生成済みなら true。
     */
    bool         HasEnvCubemap() const noexcept { return static_cast<bool>(m_EnvCube); }

    /**
     * 拡散 irradiance cubemap を返す。
     *
     * @return irradiance cubemap (64x64x6 R11G11B10_Float)。EnsureIrradiance 完了前は nullptr。
     */
    IRhiTexture* IrradianceMap()    const noexcept { return m_IrradianceCube.Get(); }

    /**
     * 拡散 irradiance cubemap が生成済みかを返す。
     *
     * @return 生成済みなら true。
     */
    bool         HasIrradianceMap() const noexcept { return static_cast<bool>(m_IrradianceCube); }

    /**
     * specular prefilter cubemap を返す。
     *
     * @return prefilter cubemap (512x512x6 R11G11B10_Float, 7 mips)。EnsurePrefilter 完了前は nullptr。
     */
    IRhiTexture* PrefilterMap()    const noexcept { return m_PrefilterCube.Get(); }

    /**
     * specular prefilter cubemap が生成済みかを返す。
     *
     * @return 生成済みなら true。
     */
    bool         HasPrefilterMap() const noexcept { return static_cast<bool>(m_PrefilterCube); }

    /**
     * prefilter cubemap の mip 数を返す。
     *
     * @return prefilter の mip 数 (未生成なら 0)。
     */
    u32          PrefilterMips()   const noexcept { return m_PrefilterMips; }

private:
    /**
     * BRDF LUT を実際に生成する。
     *
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> BuildBrdfLut(IRhiDevice& device, IRhiCommandList& cl) noexcept;

    /**
     * env cubemap を実際に生成する。
     *
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @param sky キャプチャ元の手続き式空。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> BuildEnvCubemap(IRhiDevice& device, IRhiCommandList& cl,
                                 const FSky& sky) noexcept;

    /**
     * irradiance cubemap を実際に生成する。
     *
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> BuildIrradiance(IRhiDevice& device, IRhiCommandList& cl) noexcept;

    /**
     * prefilter cubemap を実際に生成する。
     *
     * @param device リソース生成に使う RHI デバイス。
     * @param cl コマンドを積むコマンドリスト。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> BuildPrefilter(IRhiDevice& device, IRhiCommandList& cl) noexcept;

    /**
     * skybox 描画用の PSO/CB を必要なら lazy init する。
     *
     * @param device パイプライン生成に使う RHI デバイス。
     * @param rt_format 描画先 RT の色フォーマット。
     * @param depth_format 描画先 depth フォーマット。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> EnsureSkyboxPipeline(IRhiDevice& device,
                                      EFormat rt_format, EFormat depth_format) noexcept;

    /** BRDF LUT (256x256 RG16F)。 */
    TUniquePtr<IRhiTexture>  m_BrdfLut;

    /** 環境 cubemap (1024x1024x6 R11G11B10_Float)。 */
    TUniquePtr<IRhiTexture>  m_EnvCube;

    /** 拡散 irradiance cubemap (64x64x6 R11G11B10_Float)。 */
    TUniquePtr<IRhiTexture>  m_IrradianceCube;

    /** specular prefilter cubemap (512x512x6 R11G11B10_Float, 7 mips)。 */
    TUniquePtr<IRhiTexture>  m_PrefilterCube;

    /** prefilter cubemap の mip 数。 */
    u32                     m_PrefilterMips = 0;

    /**
     * xyz = normalized direction toward the analytic direct light;
     * w = cosine of its exclusion half-angle.  w > 1 disables exclusion.
     */
    FVec4                    m_DirectLightExclusion =
        FVec4{0.0f, 1.0f, 0.0f, 2.0f};

    /** skybox preview の頂点シェーダ (lazy init)。 */
    TUniquePtr<IRhiShader>   m_SkyVs;

    /** skybox preview のピクセルシェーダ (lazy init)。 */
    TUniquePtr<IRhiShader>   m_SkyPs;

    /** skybox preview のパイプライン (lazy init)。 */
    TUniquePtr<IRhiPipeline> m_SkyPipeline;

    /** skybox preview の定数バッファ。 */
    TUniquePtr<IRhiBuffer>   m_SkyCb;

    /** skybox パイプライン生成時の RT フォーマット (再生成判定用)。 */
    EFormat                  m_SkyRtFormat    = EFormat::Unknown;

    /** skybox パイプライン生成時の depth フォーマット (再生成判定用)。 */
    EFormat                  m_SkyDepthFormat = EFormat::Unknown;

    /** BRDF LUT 生成済みフラグ。 */
    bool m_bBrdfBuilt       = false;

    /** env cubemap 生成済みフラグ。 */
    bool m_bEnvBuilt        = false;

    /** irradiance cubemap 生成済みフラグ。 */
    bool m_bIrradianceBuilt = false;

    /** prefilter cubemap 生成済みフラグ。 */
    bool m_bPrefilterBuilt  = false;
};

} // namespace acs

// ===================== render/Light2D.h =====================
// SPDX-License-Identifier: Apache-2.0
// 2D 動的ライティング + ソフト影 (Core Keeper 風) と簡易ブロブ影。
//
// FLighting2D:
//   トップダウン/横スクロール 2D 向けの動的ライト。複数のカラー点光源を
//   持ち、occluder (影を落とすもの) のシルエットからソフト影を落とす。
//   ambient を低く (暗い洞窟) しておき、光源の周りだけが照らされる Core Keeper
//   のような表現を狙う。
//
//   描画フロー (FApplication::OnCustomFrame 内):
//     li.BeginScene(cl);                       // 内部 scene RT を bind + clear
//       sb.Begin(cl,w,h); ...world を描画...; sb.End();
//     li.EndScene(cl);
//     li.BeginOccluders(cl);                   // occluder RT を黒 clear
//       sb.Begin(cl,w,h); ...影を落とすスプライトを白 tint で描画...; sb.End();
//     li.EndOccluders(cl);                     // → シルエットが occluder mask に
//     li.SetAmbient({0.06,0.06,0.09});
//     li.ClearLights();
//     li.AddLight({ {px,py}, radius, {r,g,b}, intensity, softness });
//     cl.BeginRenderToSwapchain(sc, idx, clear);
//       li.Composite(cl, w, h);                // scene × (ambient + Σ light·影) を backbuffer へ
//       sb.Begin(...); ...HUD...; sb.End();
//     cl.EndRenderToSwapchain(sc, idx);
//
//   occluder は「スプライトのシルエット」をそのまま使う (白 tint + alpha blend で
//   黒地に焼くと、不透明部分が occluder になる) ので、矩形でなくスプライト形状に
//   沿った影が落ちる。影は occluder mask を linear sample + 複数レイ (面光源近似)
//   で柔らかくする。
//
// FBlobShadow:
//   光源計算を伴わない激軽の「足元の影」。柔らかい楕円テクスチャを 1 枚持ち、
//   FSpriteBatch で暗く落とすだけ。動的ライトを使わない/負荷を抑えたい時の fallback。
//
// ACS 規約: STL/<string> 不使用、全 noexcept、TResult、非コピー。


namespace acs {

class FSpriteBatch;

/**
 * 1 個の 2D 点光源。座標はスプライトと同じピクセル空間 (左上原点)。
 */
struct FLight2D {
    /** 光源位置 (px)。 */
    FVec2 pos{0.0f, 0.0f};

    /** 光が届く半径 (px)。 */
    f32   radius   = 256.0f;

    /** 光の色 (RGB)。 */
    FVec3 color{1.0f, 1.0f, 1.0f};

    /** 明るさ倍率。 */
    f32   intensity = 1.0f;

    /** 影の柔らかさ (0=くっきり影、1=とても柔らかい penumbra)。 */
    f32   softness  = 0.5f;
};

/**
 * 2D 動的ライティング + ソフト影 (Core Keeper 風)。
 *
 * @details
 * トップダウン/横スクロール 2D 向けの動的ライト。複数のカラー点光源を持ち、occluder
 * のシルエットからソフト影を落とす。BeginScene/EndScene で世界の albedo を内部 scene RT
 * に描き、BeginOccluders/EndOccluders で影を落とすスプライトを白 tint で occluder mask
 * に焼き、Composite で scene × (ambient + Σ light·影) を現在の RT へ合成する。影は
 * occluder mask の linear sample と複数レイ (面光源近似) で柔らかくする。
 */
class FLighting2D {
public:
    /** 同時に扱える点光源の上限。 */
    static constexpr u32 kMaxLights = 16;

    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FLighting2D() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FLighting2D() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FLighting2D(const FLighting2D&)            = delete;

    /** コピー代入も禁止。 */
    FLighting2D& operator=(const FLighting2D&) = delete;

    /**
     * GPU リソース (scene/occluder RT・パイプライン・定数バッファ) を確保する。
     *
     * @details width/height が 0 のときは RT 作成を遅延し、最初の有効サイズで Resize() が作る。
     * @param device リソース生成に使う RHI デバイス。
     * @param color_format backbuffer の色フォーマット (scene/occluder RT と composite 出力をこれに合わせる)。
     * @param width 初期幅 (px)。
     * @param height 初期高さ (px)。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, EFormat color_format,
                       u32 width, u32 height) noexcept;

    /** 確保した GPU リソースを解放する。 */
    void Shutdown() noexcept;

    /**
     * 解像度変更時に内部 RT を作り直す (ウィンドウリサイズで呼ぶ)。
     *
     * @details 0 サイズや現在と同サイズ (RT 確保済み) のときは no-op。
     * @param width 新しい幅 (px)。
     * @param height 新しい高さ (px)。
     * @return 成功なら空の TResult、再確保失敗ならエラー。
     */
    TResult<void> Resize(u32 width, u32 height) noexcept;

    /**
     * 環境光を設定する。
     *
     * @param ambient 環境光の色 (低くすると暗い洞窟風)。
     */
    void SetAmbient(FVec3 ambient) noexcept { m_Ambient = ambient; }

    /** 蓄積済みの光源を全て破棄する (毎フレーム先頭で呼ぶ)。 */
    void ClearLights() noexcept { m_LightCount = 0; }

    /**
     * 点光源を 1 個追加する。
     *
     * @param light 追加する点光源。
     * @return 追加成功で true、上限 (kMaxLights) 到達で false。
     */
    bool AddLight(const FLight2D& light) noexcept;

    /**
     * 現在の光源数を返す。
     *
     * @return 蓄積済みの光源数。
     */
    u32  LightCount() const noexcept { return m_LightCount; }

    /**
     * 影の品質を設定する。
     *
     * @details 値は内部で clamp される (march_steps は 2..64、ray_count は 1..16)。
     * @param march_steps 1 レイあたりの行進数。
     * @param ray_count 面光源近似のレイ本数 (多いほど penumbra が滑らかだが重い)。
     */
    void SetShadowQuality(u32 march_steps, u32 ray_count) noexcept;

    /**
     * scene (世界の albedo) 描画 bracket を開始し、内部 scene RT を bind + clear する。
     *
     * @param cl コマンドを積むコマンドリスト。
     * @param clear scene RT のクリア色 (既定は不透明黒)。
     */
    void BeginScene(IRhiCommandList& cl, FVec4 clear = FVec4{0, 0, 0, 1}) noexcept;

    /**
     * scene 描画 bracket を終了する。
     *
     * @param cl コマンドを積むコマンドリスト。
     */
    void EndScene(IRhiCommandList& cl) noexcept;

    /**
     * occluder (影を落とすスプライト) 描画 bracket を開始し、occluder RT を黒 clear する。
     *
     * @details 白 tint で描くと不透明部分が occluder mask になる。
     * @param cl コマンドを積むコマンドリスト。
     */
    void BeginOccluders(IRhiCommandList& cl) noexcept;

    /**
     * occluder 描画 bracket を終了する。
     *
     * @param cl コマンドを積むコマンドリスト。
     */
    void EndOccluders(IRhiCommandList& cl) noexcept;

    /**
     * 現在 bind 中のターゲット (通常 backbuffer) に scene × light を合成する。
     *
     * @details 呼ぶ前に BeginRenderToSwapchain 等でターゲットを bind しておくこと。
     * @param cl コマンドを積むコマンドリスト。
     * @param screen_w 画面幅 (px、ピクセル↔UV 変換に使う)。
     * @param screen_h 画面高さ (px)。
     */
    void Composite(IRhiCommandList& cl, u32 screen_w, u32 screen_h) noexcept;

    /**
     * scene RT を返す。
     *
     * @return 世界の albedo を保持する scene RT。
     */
    IRhiTexture* SceneTexture() const noexcept { return m_SceneRt.Get(); }

    /**
     * occluder RT を返す。
     *
     * @return 遮蔽シルエットを保持する occluder RT。
     */
    IRhiTexture* OccluderTexture() const noexcept { return m_OccluderRt.Get(); }

private:
    /**
     * scene RT と occluder RT を生成する。
     *
     * @param device RT 生成に使う RHI デバイス。
     * @param w RT の幅 (px)。
     * @param h RT の高さ (px)。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreateTargets(IRhiDevice& device, u32 w, u32 h) noexcept;

    /**
     * 合成シェーダ・パイプラインを生成する。
     *
     * @param device パイプライン生成に使う RHI デバイス。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreatePipeline(IRhiDevice& device) noexcept;

    /** Init で受け取った device (Resize で再利用)。 */
    IRhiDevice* m_Device      = nullptr;

    /** scene/occluder RT と composite 出力の色フォーマット。 */
    EFormat     m_ColorFormat = EFormat::B8G8R8A8_UNorm;

    /** 現在の RT 幅 (px)。 */
    u32         m_Width       = 0;

    /** 現在の RT 高さ (px)。 */
    u32         m_Height      = 0;

    /** 世界の albedo を描く scene RT。 */
    TUniquePtr<IRhiTexture>  m_SceneRt;

    /** 影を落とすシルエットを焼く occluder RT (白=遮蔽)。 */
    TUniquePtr<IRhiTexture>  m_OccluderRt;

    /** 合成パスの頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** 合成パスのピクセルシェーダ (ライト・影計算)。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** 合成パスのパイプライン。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;

    /** ライト・画面パラメータを渡す定数バッファ。 */
    TUniquePtr<IRhiBuffer>   m_Cb;

    /** 環境光の色。 */
    FVec3     m_Ambient{0.08f, 0.08f, 0.10f};

    /** 蓄積中の点光源配列。 */
    FLight2D  m_Lights[kMaxLights]{};

    /** 蓄積済みの光源数。 */
    u32       m_LightCount  = 0;

    /** 影レイの行進数。 */
    u32       m_MarchSteps  = 24;

    /** 面光源近似のレイ本数。 */
    u32       m_RayCount    = 6;
};

/**
 * 光源計算なしの簡易ブロブ影 (足元の楕円)。
 *
 * @details
 * 柔らかい楕円テクスチャを 1 枚持ち、FSpriteBatch で暗く落とすだけの激軽な「足元の影」。
 * 動的ライトを使わない/負荷を抑えたいときの fallback / 補助に使う。
 */
class FBlobShadow {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FBlobShadow() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FBlobShadow() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FBlobShadow(const FBlobShadow&)            = delete;

    /** コピー代入も禁止。 */
    FBlobShadow& operator=(const FBlobShadow&) = delete;

    /**
     * 柔らかい放射状グラデーションのテクスチャを 1 枚生成する。
     *
     * @details resolution は内部で 16..64 に clamp される。
     * @param device テクスチャ生成に使う RHI デバイス。
     * @param resolution 影テクスチャの一辺の解像度 (px)。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, u32 resolution = 64) noexcept;

    /** 確保した GPU リソースを解放する。 */
    void Shutdown() noexcept;

    /**
     * (cx,cy) 中心に w×h の柔らかい影を sb 経由で描く (要 sb.Begin 済み)。
     *
     * @param sb 描画に使う FSpriteBatch。
     * @param cx 影の中心 X (px)。
     * @param cy 影の中心 Y (px)。
     * @param w 影の幅 (px)。
     * @param h 影の高さ (px)。
     * @param alpha 影の濃さ。
     * @param color 影の色 (既定は黒)。
     */
    void Draw(FSpriteBatch& sb, f32 cx, f32 cy, f32 w, f32 h,
              f32 alpha = 0.5f, FVec3 color = FVec3{0, 0, 0}) noexcept;

    /**
     * 影テクスチャを返す。
     *
     * @return 放射状グラデーションの影テクスチャ。
     */
    IRhiTexture* Texture() const noexcept { return m_Tex.Get(); }

private:
    /** 放射状グラデーションの影テクスチャ。 */
    TUniquePtr<IRhiTexture> m_Tex;
};

} // namespace acs

// ===================== render/MotionVector.h =====================
// SPDX-License-Identifier: Apache-2.0
// motion + normal G-buffer の geometry pass
//
// シーンの全 mesh を再ラスタライズし、MRT 2 枚を書き出す:
//   - motion (RG16F)  : screen-space motion vector (prev_uv - curr_uv)。camera
//                       動きと object 動きの両方を含む (前フレームの model + VP)。
//                       TAA が history を正確に reproject し ghost / trail を消す。
//   - normal (RGBA16F): world-space normal。頂点法線をピクセル補間したもので、
//                       depth-derivative の cross(ddx,ddy) と違い曲面でも段差が
//                       出ない。SSR/SSGI/SSAO がこれを sample し、faceted な
//                       反射ベクトル由来のジャギーを根本解消する。
//
// depth からの camera reprojection のみでは動く mesh が ghost するため、
// 本モジュールがその穴を埋める。
//
// 設計:
//   - FShadowMap と同じ Begin/DrawMesh/End パターン (caller がシーンを描く)
//   - 全 mesh を描く前提 (静的 mesh は prev_model == model)。motion texture は
//     画面全体で authoritative になり、TAA は depth を併用せず済む
//     (→ TAA resolve PSO の texture slot を増やさず slot binding 問題を回避)
//   - occlusion 用に専用 depth buffer を内部に持つ (scene depth は共有しない)
//
// 使い方:
//   FMotionVector mv;
//   mv.Init(*dev, w, h);
//   ...毎フレーム (シーン color pass のあと):
//   mv.Begin(*cl, vp_no_jitter, prev_vp_no_jitter);
//   for (each mesh) mv.DrawMesh(*cl, gm, curr_model, prev_model);
//   mv.End(*cl);
//   post_params.taa_motion_texture = mv.OutputTexture();


namespace acs {

/**
 * motion vector + world-space normal の G-buffer geometry pass。
 *
 * @details
 * シーンの全 mesh を再ラスタライズし、MRT 2 枚 (motion RG16F + normal RGBA16F) を
 * 書き出す。motion は screen-space motion vector (prev_uv - curr_uv) で camera 動きと
 * object 動きの両方を含み、TAA が history を正確に reproject して ghost/trail を消す。
 * normal は頂点法線をピクセル補間した world-space 法線で、SSR/SSGI/SSAO が sample する。
 * FShadowMap と同じ Begin/DrawMesh/End パターンで、occlusion 用 depth を内部に持つ。
 */
class FMotionVector {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FMotionVector() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FMotionVector() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FMotionVector(const FMotionVector&)            = delete;

    /** コピー代入も禁止。 */
    FMotionVector& operator=(const FMotionVector&) = delete;

    /**
     * GPU リソース (RT 2 枚 + depth + パイプライン) を確保する。
     *
     * @param device RT・パイプライン生成に使う RHI デバイス。
     * @param width 出力 G-buffer の幅。
     * @param height 出力 G-buffer の高さ。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, u32 width, u32 height) noexcept;

    /** 確保した GPU リソースを解放する (多重呼び出し安全)。 */
    void Shutdown() noexcept;

    /**
     * 解像度変更時に内部 RT を作り直す (ウィンドウリサイズで呼ぶ)。
     *
     * @param width 新しい出力 G-buffer の幅。
     * @param height 新しい出力 G-buffer の高さ。
     * @return 成功なら空の TResult、再確保失敗ならエラー。
     */
    TResult<void> Resize(u32 width, u32 height) noexcept;

    /**
     * モーションパスを開始する (motion RT を 0 クリア + 内部 depth を bind してパイプライン設定)。
     *
     * @details motion vector は jitter なしの VP で計算する (TAA jitter は color pass 専用)。
     * @param cl コマンドを積むコマンドリスト。
     * @param view_proj 現フレームの jitter なし VP。
     * @param prev_view_proj 前フレームの jitter なし VP。
     */
    void Begin(IRhiCommandList& cl,
               const FMat4& view_proj, const FMat4& prev_view_proj) noexcept;

    /**
     * 1 mesh の motion vector を描画する。
     *
     * @details 静的 mesh は prev_model に model と同値を渡す。
     * @param cl コマンドを積むコマンドリスト。
     * @param mesh 描画する GPU mesh。
     * @param model 現フレームの model 行列。
     * @param prev_model 前フレームの model 行列。
     */
    void DrawMesh(IRhiCommandList& cl, const FGpuMesh& mesh,
                  const FMat4& model, const FMat4& prev_model) noexcept;

    /**
     * モーションパスを終了する (main pass の RT へ復帰)。
     *
     * @param cl コマンドを積むコマンドリスト。
     */
    void End(IRhiCommandList& cl) noexcept;

    /**
     * 出力 motion vector テクスチャを返す。
     *
     * @return motion RT (RG16F、.rg = prev_uv - curr_uv)。
     */
    IRhiTexture* OutputTexture() const noexcept { return m_Motion.Get(); }

    /**
     * 出力 world-space normal テクスチャを返す。
     *
     * @return normal RT (RGBA16F、.xyz = normalized world normal)。
     */
    IRhiTexture* OutputNormalTexture() const noexcept { return m_Normal.Get(); }

private:
    /**
     * 出力 RT (motion + normal) と内部 depth を生成する。
     *
     * @param device RT 生成に使う RHI デバイス。
     * @param w 出力幅。
     * @param h 出力高さ。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreateTargets(IRhiDevice& device, u32 w, u32 h) noexcept;

    /**
     * G-buffer 描画用の VS/PS/PSO を生成する。
     *
     * @param device パイプライン生成に使う RHI デバイス。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreatePipeline(IRhiDevice& device) noexcept;

    /** Init で受け取った device (Resize で再利用)。 */
    IRhiDevice*             m_Device = nullptr;

    /** 出力 G-buffer の幅。 */
    u32                     m_Width  = 0;

    /** 出力 G-buffer の高さ。 */
    u32                     m_Height = 0;

    /** Begin で渡された現フレーム VP。 */
    FMat4                    m_Vp{};

    /** Begin で渡された前フレーム VP。 */
    FMat4                    m_PrevVp{};

    /** 出力 motion RT (RG16F、screen-space motion = prev_uv - curr_uv)。 */
    TUniquePtr<IRhiTexture>  m_Motion;

    /** 出力 normal RT (RGBA16F、world-space normal の .xyz)。 */
    TUniquePtr<IRhiTexture>  m_Normal;

    /** occlusion 用の内部 depth (D32、scene depth とは共有しない)。 */
    TUniquePtr<IRhiTexture>  m_Depth;

    /** G-buffer 描画の頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** motion vector と world normal を書き出すピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** G-buffer 描画のパイプライン。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;

    /**
     * Per-draw constant-buffer ring.
     *
     * A single mapped upload CB cannot be overwritten between draws in one
     * command list: raw DX12 consumes it later on the GPU and every draw would
     * otherwise observe the final object's matrices.
     */
    static constexpr u32     kObjectCbRing = 256;
    TUniquePtr<IRhiBuffer>   m_Cbs[kObjectCbRing];
    u32                      m_DrawCursor = 0;
};

} // namespace acs

// ===================== render/NormalMatrix.h =====================
// SPDX-License-Identifier: Apache-2.0


#include <cmath>

namespace acs {

/**
 * inverse-transpose normal matrix を安全に構築する。
 *
 * @details Singular scale では法線変換自体が数学的に定義できない。旧sceneの zero-axis
 * scale や非有限値を Inverse へ渡して GPU CB を NaN/Inf で汚染しないよう、相対行列式を
 * 検査し、定義不能なら deterministic な identity fallback を返す。
 */
inline FMat4 MakeSafeNormalMatrix(const FMat4& model) noexcept {
    for (u32 row = 0; row < 4; ++row) {
        for (u32 col = 0; col < 4; ++col) {
            if (!std::isfinite(model.m[row][col])) return FMat4::Identity();
        }
    }

    const f32 m00 = model.m[0][0], m01 = model.m[0][1], m02 = model.m[0][2];
    const f32 m10 = model.m[1][0], m11 = model.m[1][1], m12 = model.m[1][2];
    const f32 m20 = model.m[2][0], m21 = model.m[2][1], m22 = model.m[2][2];
    const f32 determinant =
        m00 * (m11 * m22 - m12 * m21)
      - m01 * (m10 * m22 - m12 * m20)
      + m02 * (m10 * m21 - m11 * m20);
    const f32 row0_len = std::sqrt(m00 * m00 + m01 * m01 + m02 * m02);
    const f32 row1_len = std::sqrt(m10 * m10 + m11 * m11 + m12 * m12);
    const f32 row2_len = std::sqrt(m20 * m20 + m21 * m21 + m22 * m22);
    const f32 determinant_scale = row0_len * row1_len * row2_len;
    if (!std::isfinite(determinant) || !std::isfinite(determinant_scale) ||
        determinant_scale <= 0.0f ||
        std::fabs(determinant) <= determinant_scale * 1.0e-6f) {
        return FMat4::Identity();
    }

    const FMat4 normal = Transpose(Inverse(model));
    for (u32 row = 0; row < 4; ++row) {
        for (u32 col = 0; col < 4; ++col) {
            if (!std::isfinite(normal.m[row][col])) return FMat4::Identity();
        }
    }
    return normal;
}

} // namespace acs

// ===================== render/Particles.h =====================
// SPDX-License-Identifier: Apache-2.0
// 2D パーティクルシステム（CPU プール + FSpriteBatch 描画）
//
// 用途: 火花・煙・爆発・魔法効果など、ゲームの視覚エフェクト全般。
//
// 使い方:
//   FParticleSystem ps;
//   ps.Init(2048);                           // 最大パーティクル数
//   ps.SetTexture(my_circle_tex);            // null なら 1×1 白
//
//   FEmitterDesc d;
//   d.position = FVec2{400, 300};
//   d.velocity = FVec2{0, -120};
//   d.velocity_variance = FVec2{60, 30};
//   d.gravity = FVec2{0, 200};
//   d.size_start = 32; d.size_end = 0;
//   d.color_start = FVec4{1, 0.7f, 0.2f, 1};
//   d.color_end   = FVec4{1, 0.1f, 0.0f, 0};
//   d.life_seconds = 1.0f;
//   d.rate_per_sec = 200;
//   ps.SetEmitter(d);
//
//   // 毎フレーム
//   ps.Update(dt);
//   sb.Begin(*cl, sw, sh);
//   ps.Render(sb);                           // バッチ内に追加描画
//   sb.End();
//
// プリセット:
//   ps.SetEmitter(FEmitterDesc::Fire(pos));
//   ps.SetEmitter(FEmitterDesc::Sparks(pos));
//   ps.SetEmitter(FEmitterDesc::Fountain(pos));


namespace acs {

class IRhiTexture;
class FSpriteBatch;
class FAllocator;

/**
 * エミッタのパラメータ (粒子の初期分布を決める)。
 *
 * @details
 * 各粒子は spawn 時にこの記述から初期位置・速度・寿命・サイズ・色を引く。
 * size と color は start..end を寿命比で線形補間して描画される。プリセット
 * (Fire/Sparks/Fountain/Smoke) で典型的なエフェクトを即座に構成できる。
 */
struct FEmitterDesc {
    /** エミッタの基準位置 (粒子の出現中心)。 */
    FVec2  position           = FVec2{0, 0};

    /** 出現オフセット範囲の最小 (position に min..max の乱数を加算)。 */
    FVec2  spawn_offset_min   = FVec2{0, 0};

    /** 出現オフセット範囲の最大。 */
    FVec2  spawn_offset_max   = FVec2{0, 0};

    /** 初速の基準ベクトル。 */
    FVec2  velocity           = FVec2{0, -100};

    /** 初速のばらつき (各軸 ±この値の乱数を velocity に加算)。 */
    FVec2  velocity_variance  = FVec2{30, 30};

    /** 重力加速度 (毎フレーム velocity に dt 乗算で加算。画面 Y は下が +)。 */
    FVec2  gravity            = FVec2{0, 0};

    /** 誕生時のサイズ (pixel)。 */
    f32   size_start         = 16.0f;

    /** 死亡時のサイズ (pixel。size_start から線形補間)。 */
    f32   size_end           = 0.0f;

    /** 誕生時の色 (RGBA)。 */
    FVec4  color_start        = FVec4{1, 1, 1, 1};

    /** 死亡時の色 (RGBA。color_start から線形補間)。 */
    FVec4  color_end          = FVec4{1, 1, 1, 0};

    /** 寿命の基準秒。 */
    f32   life_seconds       = 1.0f;

    /** 寿命のばらつき (±この秒の乱数を life_seconds に加算)。 */
    f32   life_variance      = 0.2f;

    /** 連続生成レート (1 秒あたりの粒子数)。 */
    f32   rate_per_sec       = 60.0f;

    /** 回転速度 (描画には未使用、v2 拡張用)。 */
    f32   rotation_speed     = 0.0f;

    /** 連続生成フラグ (false で新規生成を停止)。 */
    bool  active             = true;

    /**
     * 火 (上昇する黄〜赤の炎) のプリセットを生成する。
     *
     * @param pos エミッタの基準位置。
     * @return 火エフェクト用に設定済みの FEmitterDesc。
     */
    static FEmitterDesc Fire(FVec2 pos)     noexcept;

    /**
     * 火花 (全方位に飛び散り重力で落下) のプリセットを生成する。
     *
     * @param pos エミッタの基準位置。
     * @return 火花エフェクト用に設定済みの FEmitterDesc。
     */
    static FEmitterDesc Sparks(FVec2 pos)   noexcept;

    /**
     * 噴水 (上方へ噴き出し重力で放物落下する青い水滴) のプリセットを生成する。
     *
     * @param pos エミッタの基準位置。
     * @return 噴水エフェクト用に設定済みの FEmitterDesc。
     */
    static FEmitterDesc Fountain(FVec2 pos) noexcept;

    /**
     * 煙 (ゆっくり上昇しながら拡大する灰色) のプリセットを生成する。
     *
     * @param pos エミッタの基準位置。
     * @return 煙エフェクト用に設定済みの FEmitterDesc。
     */
    static FEmitterDesc Smoke(FVec2 pos)    noexcept;
};

/**
 * 2D パーティクルシステム (CPU プール + FSpriteBatch 描画)。
 *
 * @details
 * 火花・煙・爆発・魔法効果などの視覚エフェクト全般に使う。最大 max_particles の
 * 固定プールを確保し、FEmitterDesc に従って連続生成・物理積分・寿命管理を行う
 * (死亡粒子は swap-pop で除去)。描画は事前に Begin 済みの FSpriteBatch にバッチ追加する。
 */
class FParticleSystem {
public:
    /** 空状態で構築する (プールは Init で確保)。 */
    FParticleSystem() noexcept = default;

    /** 破棄する (Shutdown でプールを解放)。 */
    ~FParticleSystem() noexcept;

    /** コピー禁止 (粒子プールを単独所有するため)。 */
    FParticleSystem(const FParticleSystem&)            = delete;

    /** コピー代入も禁止。 */
    FParticleSystem& operator=(const FParticleSystem&) = delete;

    /**
     * max_particles ぶんの粒子プールを確保する。
     *
     * @details テクスチャは後で SetTexture で設定する。0 を渡すと 1024 に丸める。
     * @param max_particles プールの最大粒子数。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(u32 max_particles = 4096) noexcept;

    /** 粒子プールを解放する (多重呼び出し安全)。 */
    void Shutdown() noexcept;

    /**
     * 描画に使うテクスチャを設定する。
     *
     * @param tex 粒子に貼るテクスチャ。null なら DrawRect 相当の白矩形 (FSpriteBatch の内部白テクスチャ)。
     */
    void SetTexture(IRhiTexture* tex) noexcept { m_Tex = tex; }

    /**
     * エミッタ記述を設定する。
     *
     * @param d 適用する FEmitterDesc。active=true で連続生成、false で停止のみ。
     */
    void SetEmitter(const FEmitterDesc& d) noexcept { m_Emitter = d; }

    /**
     * エミッタ記述への可変参照を返す (パラメータを直接書き換える)。
     *
     * @return 内部 FEmitterDesc への参照。
     */
    FEmitterDesc& Emitter() noexcept { return m_Emitter; }

    /**
     * エミッタ記述への const 参照を返す。
     *
     * @return 内部 FEmitterDesc への const 参照。
     */
    const FEmitterDesc& Emitter() const noexcept { return m_Emitter; }

    /**
     * 1 フレーム分シミュレーションを進める (連続生成 + 物理積分 + 寿命管理)。
     *
     * @param dt 前フレームからの経過秒。
     */
    void Update(f32 dt) noexcept;

    /**
     * count 個の粒子を即座に生成する (爆発等)。
     *
     * @param count 生成する粒子数 (プール容量で頭打ち)。
     */
    void EmitBurst(u32 count) noexcept;

    /** 全粒子を即座に消滅させ、生成アキュムレータをリセットする。 */
    void Reset() noexcept { m_Active = 0; m_SpawnAccum = 0; }

    /**
     * アクティブな粒子を FSpriteBatch に積む (事前に Begin 済みであること)。
     *
     * @param sb 粒子を描画する先の FSpriteBatch。
     */
    void Render(FSpriteBatch& sb) noexcept;

    /**
     * 現在生存中の粒子数を返す。
     *
     * @return アクティブ粒子数。
     */
    u32  ActiveCount() const noexcept { return m_Active; }

    /**
     * プールの最大容量を返す。
     *
     * @return 確保済みの最大粒子数。
     */
    u32  Capacity()    const noexcept { return m_Capacity; }

private:
    /**
     * 1 粒子分のシミュレーション状態。
     *
     * @details プール上に連続配置され、size/color は start..end を age/life で補間する。
     */
    struct FParticle {
        /** 現在位置 (pixel)。 */
        FVec2 pos;

        /** 現在速度。 */
        FVec2 vel;

        /** 経過時間 (秒)。 */
        f32  age;

        /** 寿命 (秒。age >= life で死亡)。 */
        f32  life;

        /** 誕生時サイズ。 */
        f32  size_start;

        /** 死亡時サイズ。 */
        f32  size_end;

        /** 誕生時の色 (RGBA)。 */
        FVec4 color_start;

        /** 死亡時の色 (RGBA)。 */
        FVec4 color_end;
    };

    /** エミッタ記述に従って粒子を 1 つ生成する (容量上限なら何もしない)。 */
    void SpawnOne() noexcept;

    /**
     * xorshift で 0..1 の擬似乱数を返す。
     *
     * @return [0, 1) の乱数。
     */
    f32  RandF() noexcept;

    /**
     * a..b の一様乱数を返す。
     *
     * @param a 下限。
     * @param b 上限。
     * @return [a, b) の乱数。
     */
    f32  RandRange(f32 a, f32 b) noexcept;

    /** 粒子プールの先頭 (容量ぶん確保、所有権を持つ)。 */
    FParticle*    m_Pool         = nullptr;

    /** 粒子プールを確保したアロケータ。既定アロケータ切替後も同じ元へ返す。 */
    FAllocator* m_Allocator = nullptr;

    /** プールの最大容量。 */
    u32          m_Capacity     = 0;

    /** 現在生存中の粒子数 (プール先頭から詰めて配置)。 */
    u32          m_Active       = 0;

    /** 連続生成の小数アキュムレータ (rate_per_sec * dt の端数を蓄積)。 */
    f32          m_SpawnAccum  = 0.0f;

    /** 現在のエミッタ記述。 */
    FEmitterDesc  m_Emitter;

    /** 描画テクスチャ (非所有。null なら白矩形)。 */
    IRhiTexture* m_Tex          = nullptr;

    /** xorshift 乱数の状態シード。 */
    u32          m_Seed         = 0xC0FFEEu;
};

} // namespace acs

// ===================== render/PostProcess.h =====================
// SPDX-License-Identifier: Apache-2.0
// HDR ポストプロセス (Bloom + Tonemap) パイプライン
//
// 想定ワークフロー:
//   1) FRenderer.BeginFrame() の直前で FPostProcess.BeginScenePass()
//      → HDR R16G16B16A16_Float RT に切替
//   2) シーン (FSky, FStandardShader, FParticleSystem 等) を HDR で描画
//   3) FPostProcess.Render(cmd, swapchain_buffer)
//      → Bloom (extract → downsample → upsample) → Tonemap → Backbuffer
//   4) FRenderer.EndFrame() で Present
//
// 設計上の選択:
//   - Bloom は 5 段の mip chain (1/2, 1/4, ... 1/32) で downsample → upsample
//   - Tonemap は ACES Filmic (Narkowicz 2016 近似) → 最後に sRGB ガンマ
//   - パイプラインは Diligent backend を前提（Dx12 raw は未対応）


namespace acs {

class IRhiTexture;

/**
 * ポストプロセス効果のパラメータ一式。
 *
 * @details
 * Bloom / Tonemap / Cinematic FX / Color grading / CAS / TAA / Auto-exposure の
 * 全パラメータを保持し、FPostProcess::Render に 1 つ渡す。各メンバは既定値で
 * 「無効 or 中性」になるよう設計してある。
 */
struct FPostProcessParams {
    /** Bloom を有効にするか。 */
    bool  bloom_enabled    = true;

    /** この輝度を超えるピクセルを Bloom 元として抽出する閾値 (HDR scale)。 */
    f32   bloom_threshold  = 1.0f;

    /** Bloom を加算する強度 (0..2)。 */
    f32   bloom_intensity  = 0.6f;

    /** upsample 時の半径スケール。 */
    f32   bloom_radius     = 1.0f;

    /**
     * 隣接 mip 間の散乱率 (0=局所的、1=最広域)。
     *
     * @details 各段を等重みで加算せず、正規化した補間で合成する。0.65 前後で
     * 発光体の芯を残しつつ、白い霧のようなエネルギー増幅を防ぐ。
     */
    f32   bloom_scatter    = 0.65f;

    /** 露出 (1.0 = 中性)。 */
    f32   exposure         = 1.0f;

    /** 出力ガンマ。 */
    f32   gamma            = 2.2f;

    /**
     * Tonemap カーブの種類。
     *
     * @details
     * 0=ACES Filmic (Narkowicz)、1=AgX (Sobotka)、2=Reinhard 拡張。AgX は彩度を
     * 控えめにする tonemap (UE5 デフォルトに近い neutral look)。既存サンプル互換の
     * ため初期値は ACES。
     */
    i32   tonemap_kind     = 0;

    /** ビネット (端の暗化) 強度 0..1。 */
    f32   vignette_intensity = 0.2f;

    /** ビネットが始まる半径 (0=中心、1=端)。 */
    f32   vignette_radius    = 0.5f;

    /** 色収差: RGB の半径方向 offset。0 で無効。 */
    f32   chromatic_aberration = 0.002f;

    /** フィルムグレイン強度 0..0.1。 */
    f32   grain_intensity    = 0.015f;

    /** procedural noise のシード (FApplication から dt 累積)。 */
    f32   grain_time         = 0.0f;

    /**
     * tonemap 直前に additive 合成する SSR 出力テクスチャ (FSsr::OutputTexture())。
     *
     * @details null で SSR 無し。Bloom と並んで mix される。intensity は SSR shader 側で
     * 適用済みのため二重適用はされない。
     */
    IRhiTexture* ssr_texture = nullptr;

    /** tonemap 側での SSR の最終 mix 強度 (既定 1.0)。 */
    f32          ssr_intensity = 1.0f;

    /** カラーグレーディング (ASC-CDL 風) の彩度: 0=モノクロ、1=neutral、>1=ブースト。 */
    f32  cg_saturation   = 1.0f;

    /** カラーグレーディングのコントラスト: 0..2、中心 0.5 を pivot とした curve。 */
    f32  cg_contrast     = 1.0f;

    /** 色温度: -1=cool/blue、0=neutral、+1=warm/orange。 */
    f32  cg_temperature  = 0.0f;

    /** 色合い (tint): -1=green、0=neutral、+1=magenta。 */
    f32  cg_tint         = 0.0f;

    /** shadow 域の色 offset (足し算)。 */
    FVec3 cg_lift         = FVec3{0, 0, 0};

    /** highlight 域の色 multiplier。 */
    FVec3 cg_gain         = FVec3{1, 1, 1};

    /**
     * CAS シャープニング (AMD FSR 簡略版) の強度。
     *
     * @details カラーグレーディング後 / gamma 前に適用。0=無効、0.3=subtle、0.6=neutral、
     * 1.0=strong。負値は不可。既定で subtle に効かせ、見かけの解像感を上げる
     * (HDR-aware なので白飛び域でも破綻しない)。0 にすれば従来どおり無効。
     */
    f32  cas_strength    = 0.3f;

    /**
     * TAA (Temporal Anti-Aliasing) を有効にするか。
     *
     * @details
     * Halton jitter を FCamera で適用した上で、history と neighborhood-clamp blend して
     * resolve する。false なら tonemap は直接 HDR RT を読み、true なら Pass_TaaResolve を
     * 実行して tonemap は resolved RT を読む。
     */
    bool taa_enabled = false;

    /**
     * history 重み (現フレームを何割取り込むか)。
     *
     * @details 0.1 = 10% current + 90% history が標準。値が小さいほどスムージングが強い
     * (motion ghost も増える)。
     */
    f32  taa_blend_factor = 0.1f;

    /**
     * TAA reprojection 用の depth テクスチャ。
     *
     * @details null なら motion=0 (静的 reprojection 無し、カメラを動かすと ghost する)。
     * set すると camera motion 由来の motion vector で history を offset sample する。
     */
    IRhiTexture* taa_depth_texture = nullptr;

    /** Halton 適用前の view_proj 行列 (TAA reprojection 用)。 */
    FMat4         taa_view_proj_no_jitter{};

    /** 前フレームの view_proj 行列 (Halton 適用前、TAA reprojection 用)。 */
    FMat4         taa_prev_view_proj_no_jitter{};

    /** reactive cloud depth と scene depth の実距離比較に使う現在カメラ位置。 */
    FVec3         taa_camera_position{};

    /**
     * 動的 mesh 対応の motion vector テクスチャ (FMotionVector モジュール)。
     *
     * @details
     * 非 null なら TAA は depth reprojection の代わりにこのテクスチャで history を引く。
     * motion vector は camera 動き + object 動きの両方を含むため、動く mesh の ghost/trail が
     * 消える。null なら従来の depth reprojection にフォールバックする。depth slot (t2) を
     * 再利用して bind するため TAA resolve PSO の slot 数は不変。
     */
    IRhiTexture* taa_motion_texture = nullptr;

    /**
     * TAA history を現在フレームへ置換する reactive mask。
     *
     * @details RG の R 成分をカメラからの距離、G 成分を coverage として読む。
     * taa_depth_texture と taa_camera_position で scene の実距離を復元し、scene より
     * 手前に見えている coverage だけを reactive とする。ボリューメトリック雲のように
     * 独自の temporal resolve を済ませた要素を渡すと、その画素と 1 px の境界帯では
     * global TAA history を混ぜない。これによりジオメトリの TAA は維持しつつ、雲へ
     * 二重に history を掛ける ghost/trail を防ぐ。null なら reactive mask は無効。
     */
    IRhiTexture* taa_reactive_texture = nullptr;

    /**
     * Auto-exposure を有効にするか。
     *
     * @details
     * false なら exposure をそのまま使う (既存サンプル互換)。true なら luma reduction →
     * 露出順応 → ExposureApply の 3 pass を内部で実行し、露出はシーン輝度から自動算出される。
     * このとき exposure は「自動露出にさらに掛ける手動補正 (EV compensation)」として働く
     * (中性 = 1.0)。
     */
    bool auto_exposure_enabled = false;

    /** 露出後の目標平均輝度。大きいほど明るく写る。 */
    f32  auto_exposure_key     = 0.5f;

    /** 自動露出の下限 (明所での白飛びを防ぐ)。 */
    f32  auto_exposure_min     = 0.05f;

    /** 自動露出の上限 (暗所での黒つぶれを防ぐ)。 */
    f32  auto_exposure_max     = 12.0f;

    /** eye adaptation 速度 (/秒、大きいほど速く順応)。 */
    f32  auto_exposure_speed   = 1.8f;

    /** 露出順応の時間補間に使うフレーム時間。 */
    f32  delta_time            = 0.0166f;

    /**
     * Replaces non-finite values with defaults and clamps bounded controls to
     * the ranges accepted by the post-process shaders.
     *
     * @details Render() sanitizes a local copy automatically. Editor/property
     * systems may call this method to normalize values before displaying them.
     */
    void Sanitize() noexcept;
};

/**
 * HDR ポストプロセス (Bloom + Tonemap + 各種効果) パイプライン。
 *
 * @details
 * シーンを HDR R16G16B16A16_Float RT に描画した後、Bloom (extract → downsample →
 * upsample) → 任意の TAA resolve → Tonemap (ACES/AgX/Reinhard) → backbuffer の順に
 * 処理する。auto-exposure 有効時は luma 測定と露出順応 pass を追加で挟む。Diligent
 * backend を前提とし、GPU リソースを単独所有する non-copy 型。
 */
class FPostProcess {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FPostProcess() noexcept = default;

    /** 破棄する (確保した GPU リソースを解放)。 */
    ~FPostProcess() noexcept;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FPostProcess(const FPostProcess&) = delete;

    /** コピー代入も禁止。 */
    FPostProcess& operator=(const FPostProcess&) = delete;

    /**
     * HDR RT + Bloom mip chain + Tonemap パイプラインを作成する。
     *
     * @param device リソース・パイプライン生成に使う RHI デバイス。
     * @param width 出力解像度の幅 (通常はバックバッファサイズ)。
     * @param height 出力解像度の高さ。
     * @param color_format 最終出力 (バックバッファ) のフォーマット。
     * @return 成功なら空の TResult、確保失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device, u32 width, u32 height,
                       EFormat color_format) noexcept;

    /** 確保した GPU リソースを解放する。 */
    void Shutdown() noexcept;

    /**
     * ウィンドウサイズ変更時に HDR RT 等を再作成する。
     *
     * @param width 新しい出力幅。
     * @param height 新しい出力高さ。
     * @return 成功なら空の TResult、再確保失敗ならエラー。
     */
    TResult<void> Resize(u32 width, u32 height) noexcept;

    /**
     * シーンを描画する HDR RT を返す (FRenderer がここに描画する)。
     *
     * @return HDR R16G16B16A16_Float のレンダーターゲット。
     */
    IRhiTexture* HdrRenderTarget() const noexcept { return m_HdrRt.Get(); }

    /**
     * HDR RT のフォーマットを返す。
     *
     * @return HDR RT のフォーマット (既定 R16G16B16A16_Float)。
     */
    EFormat       HdrFormat()       const noexcept { return m_HdrFormat; }

    /**
     * Bloom + Tonemap (+ 任意の TAA / auto-exposure) を実行し swapchain buffer へ書き出す。
     *
     * @param cmd 既に Begin 済みのコマンドリスト。
     * @param swapchain 出力先 (backbuffer をこのインスタンスから取り出す)。
     * @param buffer_index AcquireNextImage の戻り値。
     * @param params 適用する効果のパラメータ。
     */
    void Render(IRhiCommandList& cmd, IRhiSwapchain& swapchain, u32 buffer_index,
                const FPostProcessParams& params) noexcept;

private:
    /**
     * Bloom mip chain の段数 (1/2 から 1/64 までの 6 段)。
     *
     * @details Downsample は Jimenez 13-tap。段数を増やすと «より低周波 (広い)» の soft glow まで
     * 届き、UE5 風の広く柔らかい bloom になる。段数増による強度 lift は progressive upsample radius
     * (深い mip ほど tent を広げる) と bloom_intensity 側で吸収する。各 mip は 1px までクランプ確保。
     */
    static constexpr u32 kBloomMips = 6;

    /**
     * HDR RT と Bloom mip chain を生成する。
     *
     * @param device RT 生成に使う RHI デバイス。
     * @param w 出力幅。
     * @param h 出力高さ。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreateRenderTargets(IRhiDevice& device, u32 w, u32 h) noexcept;

    /**
     * 全パスのシェーダとパイプラインを生成する。
     *
     * @param device パイプライン生成に使う RHI デバイス。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> CreatePipelines(IRhiDevice& device) noexcept;

    /**
     * Bloom 抽出パス: シーン入力から閾値超えの輝度を bloom_mips[0] へ書く。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param p 適用する効果のパラメータ。
     */
    void Pass_Extract  (IRhiCommandList& cmd, const FPostProcessParams& p) noexcept;

    /**
     * Bloom downsample パス: bloom_mips[from_mip] を次段へ 13-tap で縮約する。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param from_mip 入力元の mip 段。
     */
    void Pass_Downsample(IRhiCommandList& cmd, u32 from_mip) noexcept;

    /**
     * Bloom upsample パス: 下段を 1 段上へ additive 合成する。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param to_mip 合成先の mip 段。
     * @param radius upsample 時の半径スケール。
     */
    void Pass_Upsample (IRhiCommandList& cmd, u32 to_mip, f32 radius, f32 scatter) noexcept;

    /**
     * Bloom separable Gaussian blur: 1 つの mip を H or V 方向に 1 次元ガウスぼかしする。
     * H パス (mip→tmp) と V パス (tmp→mip) を続けて呼ぶと «円形» の 2D ガウスになる。
     * box mip チェーンと違い点光源が四角くならない (DirectXTK 風)。
     *
     * @param cmd コマンドリスト。
     * @param mip 対象 mip 段 (m_BloomMips[mip] ↔ m_BloomTmp[mip])。
     * @param horizontal true=水平パス (mip→tmp)、false=垂直パス (tmp→mip)。
     * @param amount ガウスの広がり (texel 単位の step スケール)。
     */
    void Pass_GaussianBlur(IRhiCommandList& cmd, u32 mip, bool horizontal, f32 amount) noexcept;

    /**
     * TAA resolve パス: 現フレームと history を neighborhood-clamp blend する。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param p 適用する効果のパラメータ。
     */
    void Pass_TaaResolve(IRhiCommandList& cmd, const FPostProcessParams& p) noexcept;

    /**
     * Tonemap パス: HDR + Bloom を合成し tonemap して backbuffer へ書く。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param sc 出力先スワップチェーン。
     * @param buf_idx 書き出すバックバッファの index。
     * @param p 適用する効果のパラメータ。
     */
    void Pass_Tonemap  (IRhiCommandList& cmd, IRhiSwapchain& sc, u32 buf_idx,
                        const FPostProcessParams& p) noexcept;

    /**
     * Auto-exposure: HDR を log2 輝度の mip chain に縮約する luma reduction パス。
     *
     * @param cmd コマンドを積むコマンドリスト。
     */
    void Pass_LumaReduce  (IRhiCommandList& cmd) noexcept;

    /**
     * Auto-exposure: 測定した平均輝度から目標露出へ eye adaptation で順応させる。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param p 適用する効果のパラメータ。
     */
    void Pass_ExposureAdapt(IRhiCommandList& cmd, const FPostProcessParams& p) noexcept;

    /**
     * Auto-exposure: 順応済み露出を HDR に掛けて m_ExposedRt へ書く。
     *
     * @param cmd コマンドを積むコマンドリスト。
     */
    void Pass_ExposureApply(IRhiCommandList& cmd) noexcept;

    /**
     * 下流パス (TAA / Bloom / Tonemap) が読むシーン texture を返す。
     *
     * @param p 適用する効果のパラメータ。
     * @return auto-exposure 有効なら露出適用後の m_ExposedRt、そうでなければ raw m_HdrRt。
     */
    IRhiTexture* SceneInput(const FPostProcessParams& p) const noexcept;

    /**
     * 同一フレーム内の各 fullscreen draw 専用 Post CB を取得する。
     *
     * @details Raw DX12 の cpu_writable buffer はフレーム間のみリング化されるため、同じ
     * buffer を複数パスで Update すると、実行時に全 draw が最後の値を読む。各 draw に
     * 別 resource を割り当てて GPU address を固定する。
     * @return 次の CB。1 フレームの上限を超えた場合は null。
     */
    IRhiBuffer* AcquirePostCb() noexcept;

    /** Init で受け取った device (Resize で再利用)。 */
    IRhiDevice* m_Device = nullptr;

    /** 出力解像度の幅。 */
    u32         m_Width  = 0;

    /** 出力解像度の高さ。 */
    u32         m_Height = 0;

    /** 最終出力 (バックバッファ) のフォーマット。 */
    EFormat      m_ColorFormat = EFormat::B8G8R8A8_UNorm;

    /** HDR RT のフォーマット。 */
    EFormat      m_HdrFormat   = EFormat::R16G16B16A16_Float;

    /** メイン HDR RT (シーン描画先)。 */
    TUniquePtr<IRhiTexture> m_HdrRt;

    /** Bloom mip chain (各段は HDR、解像度は半分ずつ)。 */
    TUniquePtr<IRhiTexture> m_BloomMips[kBloomMips];

    /** Bloom separable Gaussian の ping-pong 用テンポラリ (各 mip と同サイズ)。 */
    TUniquePtr<IRhiTexture> m_BloomTmp[kBloomMips];

    /** 共通の全画面三角形 VS。 */
    TUniquePtr<IRhiShader>   m_VsFullscreen;

    /** Bloom 抽出パスのピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsExtract;

    /** Bloom downsample パスのピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsDownsample;

    /** Bloom upsample パスのピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsUpsample;

    /** Bloom separable Gaussian blur パスのピクセルシェーダ (DirectXTK 風、H/V 2 パスで円形)。 */
    TUniquePtr<IRhiShader>   m_PsGaussian;

    /** Tonemap パスのピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsTonemap;

    /** Bloom 抽出パイプライン (HDR → bloom_mips[0])。 */
    TUniquePtr<IRhiPipeline> m_PipeExtract;

    /** Bloom downsample パイプライン (bloom_mips[i] → bloom_mips[i+1])。 */
    TUniquePtr<IRhiPipeline> m_PipeDownsample;

    /** Bloom upsample パイプライン (bloom_mips[i+1] + bloom_mips[i] → bloom_mips[i])。 */
    TUniquePtr<IRhiPipeline> m_PipeUpsample;

    /** Bloom Gaussian blur パイプライン (separable、Opaque)。 */
    TUniquePtr<IRhiPipeline> m_PipeGaussian;

    /** Tonemap パイプライン (HDR + bloom_mips[0] → backbuffer)。 */
    TUniquePtr<IRhiPipeline> m_PipeTonemap;

    /**
     * 各 fullscreen draw のパラメータを固定する Post CB ring。
     *
     * @details 最大構成は luma 13 + TAA 1 + bloom 14 + tonemap 1 draw。将来の
     * パス追加にも余裕を持たせて 64 本確保し、Render 冒頭で cursor を戻す。
     */
    static constexpr u32     kPostCbRing = 64;
    TUniquePtr<IRhiBuffer>   m_CbPost[kPostCbRing];
    u32                      m_PostCbCursor = 0;

    /**
     * TAA の ping-pong history RT。
     *
     * @details m_Taa[N%2] が current frame の resolved 出力、m_Taa[(N+1)%2] が previous frame の
     * resolved 出力 (= history input)。frame index で role を swap する。
     */
    TUniquePtr<IRhiTexture>  m_Taa[2];

    /** TAA resolve パスのピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsTaaResolve;

    /** TAA resolve パイプライン。 */
    TUniquePtr<IRhiPipeline> m_PipeTaaResolve;

    /** TAA の現フレーム index (history ping-pong 用)。 */
    u32                     m_TaaFrame = 0;

    /** TAA reprojection 用の行列 2 枚を渡す CB (separate b1)。 */
    TUniquePtr<IRhiBuffer>   m_CbTaaReproj;

    /** depth 未指定時の fallback depth テクスチャ (1x1)。 */
    TUniquePtr<IRhiTexture>  m_TaaDepthFb;

    /** Bloom / SSR が無い texture slot に必ず bind する 1x1 黒テクスチャ。 */
    TUniquePtr<IRhiTexture>  m_BlackFb;

    /**
     * Auto-exposure の最大 luma mip 段数。
     *
     * @details 4K (3840) でも floor(log2)+1 に収まる値。
     */
    static constexpr u32 kMaxLumaMips = 13;

    /**
     * 平均輝度測定用の luma mip chain。
     *
     * @details m_HdrRt の 1/2 から 1x1 まで縮約する。最深段 (1x1) にシーン平均 log2 輝度が入る。
     */
    TUniquePtr<IRhiTexture>  m_LumaMips[kMaxLumaMips];

    /** 実際に確保した luma mip の段数。 */
    u32                     m_LumaMipCount = 0;

    /**
     * 順応済み露出を保持する 1x1 ping-pong テクスチャ。
     *
     * @details frame N が m_Exposure[N%2] に書き、m_Exposure[(N+1)%2] = 前フレーム値を読む。
     */
    TUniquePtr<IRhiTexture>  m_Exposure[2];

    /** m_HdrRt に自動露出を掛けた結果 (下流パスはこれを読む)。 */
    TUniquePtr<IRhiTexture>  m_ExposedRt;

    /** HDR → log2 輝度の抽出 (downsample 兼) ピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsLumaExtract;

    /** log2 輝度を box average で縮約するピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsLumaDown;

    /** 露出順応 (eye adaptation) のピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsExposure;

    /** m_HdrRt * 露出 → m_ExposedRt のピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_PsExposeApply;

    /** luma 抽出パイプライン。 */
    TUniquePtr<IRhiPipeline> m_PipeLumaExtract;

    /** luma downsample パイプライン。 */
    TUniquePtr<IRhiPipeline> m_PipeLumaDown;

    /** 露出順応パイプライン。 */
    TUniquePtr<IRhiPipeline> m_PipeExposure;

    /** 露出適用パイプライン。 */
    TUniquePtr<IRhiPipeline> m_PipeExposeApply;

    /** auto-exposure 用パラメータ CB。 */
    TUniquePtr<IRhiBuffer>   m_CbAuto;

    /** 露出 ping-pong / cold-start 判定に使うフレームカウンタ。 */
    u32                     m_AutoFrame = 0;

    /** luma mip / 露出テクスチャのフォーマット。 */
    EFormat                  m_LumaFormat = EFormat::R16G16_Float;
};

} // namespace acs

// ===================== render/RefractionShader.h =====================
// SPDX-License-Identifier: Apache-2.0
// スクリーンスペース屈折シェーダ
//
// 用途: ガラス・水・氷のような透明屈折オブジェクトを描画する。屈折は
//       「描画済みの opaque シーン (background) を、屈折方向にずらして
//       sample する」スクリーンスペース手法で表現する。
//
// 前提となるフレーム構成 (呼び出し側 = サンプルが用意する):
//   1. opaque ジオメトリを HDR RT へ描画する
//   2. HDR RT を background テクスチャへ複製する (屈折オブジェクトが読むため。
//      同一 RT の read+write は不可なので複製が要る)
//   3. FRefractionShader で屈折オブジェクトを HDR RT へ描画する (background を sample)
//
// 使い方:
//   FRefractionShader refr;
//   refr.Init(*device, hdr_format, depth_format);
//   refr.SetFrame(camera.ViewProjection(), camera.Eye(),
//                 background_tex.Width(), background_tex.Height());
//   refr.DrawMesh(*cl, glass_mesh, model, background_tex, env_cubemap,
//                 /*ior=*/1.5f, /*thickness=*/0.5f, /*tint=*/FVec3{1,1,1});
//
// blend は Opaque。屈折オブジェクトは「背景を曲げた色」を不透明に書き込むため
// alpha blend は不要 (深度も書き、後続の描画を正しく遮蔽する)。



namespace acs {

/**
 * スクリーンスペース屈折シェーダ (ガラス・水・氷)。
 *
 * @details
 * 描画済みの opaque シーン (background) を屈折方向へずらして sample することで透明屈折
 * オブジェクトを表現する。blend は Opaque で深度も書き、後続の描画を正しく遮蔽する。
 * GPU リソースを単独所有する non-copy 型。
 */
class FRefractionShader {
public:
    /** 空状態で構築する (GPU リソースは Init で確保)。 */
    FRefractionShader() noexcept = default;

    /** 破棄する (GPU リソースは TUniquePtr が解放)。 */
    ~FRefractionShader() noexcept = default;

    /** コピー禁止 (GPU リソースを単独所有するため)。 */
    FRefractionShader(const FRefractionShader&)            = delete;

    /** コピー代入も禁止。 */
    FRefractionShader& operator=(const FRefractionShader&) = delete;

    /**
     * VS+PS のコンパイル・パイプライン・定数バッファを生成する。
     *
     * @param device リソース・パイプライン生成に使う RHI デバイス。
     * @param rt_format 描画先 RT のフォーマット (通常 HDR = R16G16B16A16_Float)。
     * @param depth_format 深度フォーマット (opaque pass と同じものを渡す)。
     * @return 成功なら空の TResult、生成失敗ならエラー。
     */
    TResult<void> Init(IRhiDevice& device,
                      EFormat rt_format    = EFormat::B8G8R8A8_UNorm,
                      EFormat depth_format = EFormat::D32_Float) noexcept;

    /** 確保した全リソースを解放する。 */
    void Shutdown() noexcept;

    /**
     * 毎フレームのカメラ情報を設定する。
     *
     * @param view_projection カメラの view-projection 行列。
     * @param camera_pos world 空間の eye 位置。
     * @param screen_w 主パス/background texture の幅。0 なら直前値を維持する。
     * @param screen_h 主パス/background texture の高さ。0 なら直前値を維持する。
     */
    void SetFrame(const FMat4& view_projection, FVec3 camera_pos,
                  u32 screen_w = 0, u32 screen_h = 0) noexcept;

    /** 現在の屈折background幅を返す (描画診断・resize検証用)。 */
    u32 ScreenWidth() const noexcept { return m_ScreenW; }

    /** 現在の屈折background高さを返す (描画診断・resize検証用)。 */
    u32 ScreenHeight() const noexcept { return m_ScreenH; }

    /**
     * per-pixel 厚み計測用に背面深度マップを設定する。
     *
     * @details
     * 背面 (cull=Front で描いた) 深度を渡すと、各 pixel の表面/背面 view-space z 差から
     * 実厚みを計算し、Beer-Lambert 吸収 (tint^thickness) と屈折オフセットの両方で使う。
     * SetObject のスカラー thickness は back_depth が無いか enabled=0 のときの fallback。
     * @param back_depth 透明オブジェクトの背面深度を焼いた D32_Float (shader_visible_depth=true)。null で従来のスカラー厚みに戻る。
     * @param near カメラの透視 near (NDC depth → view-space z 逆変換に使う)。
     * @param far カメラの透視 far (NDC depth → view-space z 逆変換に使う)。
     * @param screen_w 主パス HDR RT の幅 (SV_POSITION から UV を作るため)。
     * @param screen_h 主パス HDR RT の高さ。
     */
    void SetBackDepth(IRhiTexture* back_depth, f32 near, f32 far,
                       u32 screen_w, u32 screen_h) noexcept;

    /**
     * 描画オブジェクトごとのマテリアルを設定する。
     *
     * @param model オブジェクトの world 変換行列。
     * @param ior 屈折率 (ガラス~1.5、水~1.33、ダイヤ~2.4)。
     * @param thickness 屈折方向に背景を sample する距離 (大きいほど歪みが強い)。back_depth がセット済みなら per-pixel 計測値が優先され、本引数は fallback。
     * @param tint ガラスの吸収色 (透明=白、色付きガラス=その色)。
     * @param roughness 表面荒さ (0=クリア、1=完全フロステッド)。
     * @param dispersion 色収差/分散 (0=色分離無し、1=強プリズム/ダイヤ風)。
     * @param env_mip_levels 反射環境マップの mip 数 (roughness の LOD 選択用)。
     */
    void SetObject(const FMat4& model, f32 ior, f32 thickness, FVec3 tint,
                   f32 roughness = 0.0f, f32 dispersion = 0.0f,
                   u32 env_mip_levels = 1) noexcept;

    /**
     * 屈折描画パイプラインを返す。
     *
     * @return 屈折描画のパイプライン。
     */
    IRhiPipeline* Pipeline()    const noexcept { return m_Pipeline.Get(); }

    /**
     * per-frame 定数バッファを返す。
     *
     * @return view-projection / eye 位置などを格納する CB。
     */
    IRhiBuffer*   PerFrameCB()  const noexcept { return m_FrameCb.Get(); }

    /**
     * per-object 定数バッファを返す。
     *
     * @return model 行列やマテリアルを格納する CB。
     */
    IRhiBuffer*   PerObjectCB() const noexcept {
        return m_CurrentObjectCb < kObjectCbRing
             ? m_ObjectCbs[m_CurrentObjectCb].Get()
             : nullptr;
    }

    /**
     * 1 関数で 1 体描画する (SetObject + CB/Texture バインド + DrawIndexed をまとめる)。
     *
     * @param cmd コマンドを積むコマンドリスト。
     * @param mesh 描画する屈折メッシュ。
     * @param model オブジェクトの world 変換行列。
     * @param background 屈折で sample する opaque シーンの複製。
     * @param env Fresnel 反射に使う環境キューブマップ。
     * @param ior 屈折率 (ガラス~1.5、水~1.33、ダイヤ~2.4)。
     * @param thickness 屈折方向に背景を sample する距離 (大きいほど歪みが強い)。
     * @param tint ガラスの吸収色 (透明=白、色付きガラス=その色)。
     * @param roughness 表面荒さ (0=clear、>0 で多タップでブラー = frosted)。
     * @param dispersion 色収差/分散 (0=なし、>0 でプリズム/ダイヤ風の色分離)。
     */
    void DrawMesh(IRhiCommandList& cmd, const FGpuMesh& mesh, const FMat4& model,
                  IRhiTexture& background, IRhiTexture& env,
                  f32 ior = 1.5f, f32 thickness = 0.5f,
                  FVec3 tint = FVec3{1, 1, 1},
                  f32 roughness = 0.0f,
                  f32 dispersion = 0.0f) noexcept;

private:
    /** 屈折オブジェクトの頂点シェーダ。 */
    TUniquePtr<IRhiShader>   m_Vs;

    /** 背景を屈折 sample するピクセルシェーダ。 */
    TUniquePtr<IRhiShader>   m_Ps;

    /** 屈折描画のパイプライン。 */
    TUniquePtr<IRhiPipeline> m_Pipeline;

    /** per-frame 定数バッファ (view-projection / eye)。 */
    TUniquePtr<IRhiBuffer>   m_FrameCb;

    /**
     * per-object 定数バッファ ring (model / マテリアル)。
     *
     * @details Raw DX12 では同じ cpu_writable CB を同一フレームに再 Update すると、記録済み
     * draw も最後の値を読む。ガラス draw ごとに別 GPU address を割り当てて値を固定する。
     */
    static constexpr u32     kObjectCbRing = 64;
    TUniquePtr<IRhiBuffer>   m_ObjectCbs[kObjectCbRing];
    u32                      m_ObjectCbCursor = 0;
    u32                      m_CurrentObjectCb = kObjectCbRing;

    /** per-pixel 厚み計測用の背面深度マップ (弱参照、caller owns)。 */
    IRhiTexture*           m_BackDepth   = nullptr;

    /** enabled=0 用の 1x1 R32F fallback 深度テクスチャ。 */
    TUniquePtr<IRhiTexture> m_BackDepthFb;

    /** 背面深度を view-space z へ戻す際の near。 */
    f32                    m_BackNear    = 0.1f;

    /** 背面深度を view-space z へ戻す際の far。 */
    f32                    m_BackFar     = 100.0f;

    /** 主パス HDR RT の幅 (SV_POSITION → UV 用)。 */
    u32                    m_ScreenW     = 1;

    /** 主パス HDR RT の高さ。 */
    u32                    m_ScreenH     = 1;

    /** 背面深度マップが有効か (false なら fallback スカラー厚み)。 */
    bool                   m_bBackEnabled = false;

    /**
     * SetFrame で受け取った view-projection 行列を保持する。
     *
     * @details SetBackDepth が screen params だけ更新する際に同じ Frame CB を再書き込みする
     * ために覚えておく。
     */
    FMat4                   m_Vp           = {};

    /** SetFrame で受け取った world 空間の eye 位置 (Frame CB 再書き込み用)。 */
    FVec3                   m_Eye          = FVec3{0, 0, 0};
};

} // namespace acs

